/**
 * measureKey: one of DIBELS_MEASURES' keys (e.g. 'ORF_WORDS').
 * grade: 'K','1'..'8' (string or number).
 * season: 'Fall' | 'Winter' | 'Spring'.
 * rawScore: the number the student scored.
 * Returns { tier, meaning, bands } or null if this measure isn't
 * published for that grade/season in the source chart.
 */
function scoreDibels(measureKey, grade, season, rawScore) {
  var period = DIBELS_SEASON_TO_PERIOD[season];
  var gradeKey = normalizeGradeKey_(grade);
  var measureTable = DIBELS_BENCHMARKS[measureKey];
  var bands = measureTable && measureTable[gradeKey] && measureTable[gradeKey][period];

  if (!bands) {
    return {
      tier: null,
      meaning: 'This measure is not published for grade ' + gradeKey + ', ' + season + ' in the DIBELS 8th Edition Benchmark Goals chart.',
      bands: null
    };
  }

  // Real find, 2026-10-05 (administrator report -- a Grade 2 ORF Accuracy
  // score showed "Meeting expectations" instead of a real color tier):
  // every band pair above is published as ADJACENT WHOLE-NUMBER cutoffs
  // (one band's max is always exactly one less than the next band's min)
  // -- fine for every DIBELS measure that's a whole-number count (words/
  // letters per minute), but ORF_ACCURACY is computed as a percentage to 2
  // decimal places (Index.html, submitSession's ORF Accuracy calculation:
  // Math.round((words/attempts)*100*100)/100), e.g. 91.67. That value is
  // bigger than Green's max (91) and smaller than Blue's min (92) -- a real
  // gap between two bands that only exists because a decimal was compared
  // against cutoffs the source chart only ever publishes as whole percents.
  // No band matched, tier came back null, and the client's fallback
  // (measureStatusBadge_, Index.html) showed the generic "Meeting
  // expectations" badge instead of Green. Rounding to the nearest whole
  // number before matching is a no-op for every other DIBELS measure
  // (already whole numbers) and puts ORF_ACCURACY's percentage back in
  // line with how the chart itself was actually published.
  var matched = null;
  var scoreForBand = Math.round(rawScore);
  for (var i = 0; i < bands.length; i++) {
    var b = bands[i];
    if (scoreForBand >= b.min && (b.max === null || scoreForBand <= b.max)) {
      matched = b.tier;
      break;
    }
  }

  return {
    tier: matched,
    meaning: matched ? DIBELS_TIER_MEANING[matched] : null,
    bands: bands
  };
}

// ============================================================
//  DIBELS Composite Score — auto-calculation
//  Source: "DIBELS 8th Edition Composite Score Calculation Guide
//  Supplement" (July 2020), University of Oregon
//  (https://dibels.uoregon.edu/materials/dibels). Weights, means,
//  and standard deviations are transcribed from the per-grade
//  worksheets (pp. 11-19), which is the unambiguous version of
//  this data (an earlier compact table on pp. 6-7 renders with
//  columns visually misaligned when text-extracted). Verified by
//  hand-recomputing both worked examples in the document (a
//  Kindergarten discontinue case and a Grade 2 gating case) --
//  both matched exactly.
//
//  Formula (guide's steps 1-6):
//    1. weighted_i = round(raw_i * weight_i, 2) for each required measure
//    2. sum = total of all weighted_i
//    3. z = round((sum - mean) / sd, 2)
//    4. scaled = round(z * 40)
//    5. composite = scaled + seasonal constant
//  Note: ORF Accuracy must be a proportion (e.g. 0.96), not a
//  percent (96), in this formula specifically -- converted below.
// ============================================================

var DIBELS_COMPOSITE_PARAMS = {
  K: {
    weights: { LNF: { Fall: 35.44, Winter: 8.86, Spring: 8.86 }, PSF: 4.13, NWF_CLS: 14.93, NWF_WRC: 3.56, WRF: 5.62 },
    mean: 729, sd: 630,
    constants: { Fall: 289, Winter: 364, Spring: 398 }
  },
  '1': {
    weights: { LNF: 10.72, PSF: 2.13, NWF_CLS: 23.13, NWF_WRC: 7.79, WRF: 13.51, ORF_WORDS: 25.36, ORF_ACCURACY: 0.25 },
    mean: 3371, sd: 2251,
    constants: { Fall: 360, Winter: 400, Spring: 440 }
  },
  '2': {
    weights: { NWF_CLS: 32.74, NWF_WRC: 10.95, WRF: 21.26, ORF_WORDS: 35.36, ORF_ACCURACY: 0.15, MAZE: 4.28 },
    mean: 7085, sd: 3811,
    constants: { Fall: 360, Winter: 400, Spring: 440 }
  },
  '3': {
    weights: { NWF_CLS: 40.02, NWF_WRC: 11.80, WRF: 19.83, ORF_WORDS: 39.42, ORF_ACCURACY: 0.09, MAZE: 4.79 },
    mean: 10051, sd: 4349,
    constants: { Fall: 360, Winter: 400, Spring: 440 }
  },
  '4': {
    weights: { ORF_WORDS: 36.42, ORF_ACCURACY: 0.06, MAZE: 6.29 },
    mean: 4563, sd: 1771,
    constants: { Fall: 360, Winter: 400, Spring: 440 }
  },
  '5': {
    weights: { ORF_WORDS: 31.12, ORF_ACCURACY: 0.03, MAZE: 4.58 },
    mean: 4085, sd: 1299,
    constants: { Fall: 360, Winter: 400, Spring: 440 }
  },
  '6': {
    weights: { ORF_WORDS: 40.71, ORF_ACCURACY: 0.05, MAZE: 5.03 },
    mean: 6087, sd: 1685,
    constants: { Fall: 360, Winter: 400, Spring: 440 }
  },
  '7': {
    weights: { ORF_WORDS: 40.55, ORF_ACCURACY: 0.06, MAZE: 7.34 },
    mean: 6444, sd: 1960,
    constants: { Fall: 360, Winter: 400, Spring: 440 }
  },
  '8': {
    weights: { ORF_WORDS: 37.69, ORF_ACCURACY: 0.03, MAZE: 6.75 },
    mean: 4824, sd: 1506,
    constants: { Fall: 360, Winter: 400, Spring: 440 }
  }
};

function round2_(n) { return Math.round(n * 100) / 100; }

/**
 * rawScoresByMeasure: { LNF: 25, PSF: 40, ... } -- whichever measures were
 * actually entered this session (ORF_ACCURACY as a percent, e.g. 96, same
 * convention as everywhere else in the app -- converted to a proportion
 * internally).
 *
 * Only computes a result when EVERY measure the grade's formula requires
 * is present -- this does NOT attempt the discontinue/gating substitution-
 * constant rules from the guide (those apply only when a specific stop-
 * testing rule was invoked mid-administration, a narrower and more
 * situational case). Enter the composite manually for those sessions.
 *
 * Returns { composite, missing, note }. composite is null if it couldn't
 * be calculated (wrong/unpublished grade, or required measures missing).
 */
function computeDibelsComposite(grade, season, rawScoresByMeasure) {
  var params = DIBELS_COMPOSITE_PARAMS[normalizeGradeKey_(grade)];
  if (!params) {
    return { composite: null, missing: [], note: 'No composite formula published for grade ' + grade + '.' };
  }
  if (!params.constants[season]) {
    return { composite: null, missing: [], note: 'Unknown season: ' + season };
  }

  var requiredMeasures = Object.keys(params.weights);
  var missing = requiredMeasures.filter(function(m) {
    var v = rawScoresByMeasure[m];
    return v === undefined || v === null || v === '';
  });
  if (missing.length > 0) {
    return {
      composite: null,
      missing: missing,
      note: 'Enter all required measures to auto-calculate the composite score: ' + missing.join(', ') + '.'
    };
  }

  var sum = 0;
  requiredMeasures.forEach(function(m) {
    var weight = params.weights[m];
    if (m === 'LNF' && typeof weight === 'object') weight = weight[season];
    var raw = Number(rawScoresByMeasure[m]);
    if (m === 'ORF_ACCURACY') raw = raw / 100; // guide requires a proportion, not a percent
    sum += round2_(raw * weight);
  });

  var z = round2_((sum - params.mean) / params.sd);
  var scaled = Math.round(z * 40);
  var composite = scaled + params.constants[season];

  return { composite: composite, missing: [], note: null };
}

