// ============================================================
//  CORE Phonics Survey — Parts A-L
//  Source: CORE, Assessing Reading: Multiple Measures, 2nd Ed.,
//  2008, Arena Press — word lists + mastery cut scores transcribed
//  from the Record Form / benchmark table in
//  G:\My Drive\ELC Shared\Database\CORE Phonics Survey.pdf
//
//  Scoring model: it's a MASTERY test — students are expected to
//  eventually get every item correct. A part that was discontinued
//  under the stop-rule (2+ misses on a real-word line means the
//  pseudoword line isn't given) is simply left unchecked, which
//  correctly scores those items as not-yet-mastered — same as the
//  paper Record Form.
// ============================================================

var CORE_PHONICS_PARTS = {
  A: { label: 'Letter names — uppercase', category: 'Alphabet Skills and Letter Sounds',
       items: ['D','A','N','S','X','Z','J','L','H','T','Y','E','C','O','M','R','P','W','K','U','G','B','F','Q','V','I'] },
  B: { label: 'Letter names — lowercase', category: 'Alphabet Skills and Letter Sounds',
       items: ['d','a','n','s','x','z','j','l','h','t','y','e','c','o','m','r','p','w','k','u','g','b','f','q','v','i'] },
  C: { label: 'Consonant sounds', category: 'Alphabet Skills and Letter Sounds',
       items: ['d','l','n','s','x','z','j','t','y','p','c','h','m','r','k','w','g','b','f','q','v'] },
  D_long: { label: 'Long vowel sounds', category: 'Alphabet Skills and Letter Sounds',
       items: ['e (long)', 'i (long)', 'a (long)', 'o (long)', 'u (long)'] },
  D_short: { label: 'Short vowel sounds', category: 'Alphabet Skills and Letter Sounds',
       items: ['e (short)', 'i (short)', 'a (short)', 'o (short)', 'u (short)'] },
  E: { label: 'Short vowels in CVC words', category: 'Reading and Decoding Skills',
       items: ['sip','mat','let','bun','hog', 'rut','fit','bat','hot','set', 'nop','sut','dit','pem','fap'] },
  F: { label: 'Consonant blends with short vowels', category: 'Reading and Decoding Skills',
       items: ['stop','trap','quit','spell','plan', 'silk','fast','sank','lump','held', 'nask','dilt','qued','cang','dran'] },
  G: { label: 'Short vowels, digraphs, and -tch trigraph', category: 'Reading and Decoding Skills',
       items: ['when','chop','thin','shut','wick', 'dodge','rash','ring','then','match', 'chid','shom','dath','phid','futch'] },
  H: { label: 'R-controlled vowels', category: 'Reading and Decoding Skills',
       items: ['harm','dirt','form','fern','surf', 'worn','pert','bark','turn','bird', 'nerm','sirt','gorf','murd','carn'] },
  I: { label: 'Long vowel spellings', category: 'Reading and Decoding Skills',
       items: ['tape','key','toe','paid','feet', 'leap','boat','tie','ray','blow', 'loe','hine','beap','faim','soat'] },
  J: { label: 'Variant vowels', category: 'Reading and Decoding Skills',
       items: ['few','down','moon','hawk','coin', 'cue','loud','cook','haunt','toy', 'voot','rew','fout','zoy','bawk'] },
  K: { label: 'Low frequency vowel and consonant spellings', category: 'Reading and Decoding Skills',
       items: ['kneel','cent','type','ghost','wrist', 'giant','sweat','gnat','bomb','sigh', 'bice','knod','dimb','tigh','wrep'] },
  L: { label: 'Multisyllabic words', category: 'Reading and Decoding Skills',
       // 8 syllable-pattern rows x 3 words (real/real/pseudo) = 24 items
       items: [
         'unless','consent','timbut',
         'competes','admire','rompete',
         'depend','radishes','podated',
         'zero','menu','gromu',
         'locate','inhaled','pentate',
         'stable','dimple','morkle',
         'further','bordered','darber',
         'railways','roaring','fauntoon'
       ] }
};

var CORE_PART_ORDER = ['A', 'B', 'C', 'D_long', 'D_short', 'E', 'F', 'G', 'H', 'I', 'J', 'K', 'L'];

// Any 15-item part (E-K) shares this cut-score scale.
var CORE_15_ITEM_TIERS = [
  { tier: 'Mastery', min: 14, max: 15 },
  { tier: 'Strategic', min: 10, max: 13 },
  { tier: 'Intensive', min: 0, max: 9 }
];
// Part L (24 items).
var CORE_24_ITEM_TIERS = [
  { tier: 'Mastery', min: 21, max: 24 },
  { tier: 'Strategic', min: 15, max: 20 },
  { tier: 'Intensive', min: 0, max: 14 }
];
// Combined Alphabet Skills / Letter Names & Sounds score (A+B+C+D_long+D_short, max 83).
var CORE_83_COMBINED_TIERS = [
  { tier: 'Mastery', min: 83, max: 83 },
  { tier: 'Strategic', min: 65, max: 82 },
  { tier: 'Intensive', min: 0, max: 64 }
];

function tierFromCutTable_(score, table) {
  for (var i = 0; i < table.length; i++) {
    if (score >= table[i].min && score <= table[i].max) return table[i].tier;
  }
  return null;
}

/**
 * itemResults: { A: [bool x26], B: [bool x26], C: [bool x21], D_long: [bool x5],
 *   D_short: [bool x5], E..K: [bool x15], L: [bool x24] }
 *
 * Only parts present as a KEY in itemResults are treated as administered --
 * a part the UI never showed for this grade/season (see
 * CORE_PHONICS_AVAILABILITY below) is skipped entirely rather than scored
 * as a fake 0/Intensive result. The combined Alphabet Skills/Letter Sounds
 * score is only computed when all five of its inputs (A, B, C, D_long,
 * D_short) were actually administered.
 */
function scoreCorePhonics(itemResults) {
  itemResults = itemResults || {};
  var administeredParts = CORE_PART_ORDER.filter(function(partId) {
    return Object.prototype.hasOwnProperty.call(itemResults, partId);
  });

  var parts = {};
  administeredParts.forEach(function(partId) {
    var def = CORE_PHONICS_PARTS[partId];
    var marks = itemResults[partId] || [];
    var maxScore = def.items.length;
    var rawScore = marks.filter(function(v) { return v === true; }).length;

    var tiers = partId === 'L' ? CORE_24_ITEM_TIERS
      : (partId === 'A' || partId === 'B' || partId === 'C' || partId === 'D_long' || partId === 'D_short') ? null
      : CORE_15_ITEM_TIERS;

    parts[partId] = {
      label: def.label,
      category: def.category,
      raw_score: rawScore,
      max_score: maxScore,
      benchmark_tier: tiers ? tierFromCutTable_(rawScore, tiers) : null
    };
  });

  var alphabetParts = ['A', 'B', 'C', 'D_long', 'D_short'];
  var haveFullAlphabetBattery = alphabetParts.every(function(p) { return parts.hasOwnProperty(p); });
  var combinedRaw = null, combinedTier = null;
  if (haveFullAlphabetBattery) {
    combinedRaw = alphabetParts.reduce(function(sum, p) { return sum + parts[p].raw_score; }, 0);
    combinedTier = tierFromCutTable_(combinedRaw, CORE_83_COMBINED_TIERS);
    alphabetParts.forEach(function(p) { parts[p].benchmark_tier = combinedTier; });
  }

  var measures = {};
  if (haveFullAlphabetBattery) {
    measures.letter_names_and_sounds = {
      label: 'Alphabet Skills and Letter Sounds (combined)',
      raw_score: combinedRaw,
      max_score: 83,
      benchmark_tier: combinedTier
    };
  }
  administeredParts.forEach(function(partId) {
    measures['part_' + partId.toLowerCase()] = {
      label: 'Part ' + partId.replace('_long', ' (long)').replace('_short', ' (short)') + ' — ' + parts[partId].label,
      raw_score: parts[partId].raw_score,
      max_score: parts[partId].max_score,
      benchmark_tier: parts[partId].benchmark_tier,
      item_detail: itemResults[partId] || []
    };
  });

  return {
    measures: measures,
    summary: buildCorePhonicsSummary_(measures)
  };
}

// ============================================================
//  Grade/season availability -- from the "WHEN" chart in the
//  CORE Phonics Survey source PDF (also supplied directly as
//  Screen Shots\Core Phonics Chart.pdf). "X" cells are the
//  standard battery for that grade/season; "if indicated" cells
//  are always available at examiner discretion (not tied to
//  season); blank cells are genuinely not given at that grade/
//  season and are excluded from the entry form entirely.
// ============================================================

var CORE_PHONICS_AVAILABILITY = {
  K: {
    Fall: ['A', 'B'],
    Winter: ['A', 'B', 'C', 'D_long', 'D_short', 'E'],
    Spring: ['A', 'B', 'C', 'D_long', 'D_short', 'E']
  },
  '1': {
    Fall: ['A', 'B', 'C', 'D_long', 'D_short', 'E'],
    Winter: ['A', 'B', 'C', 'D_long', 'D_short', 'E', 'F', 'G', 'H', 'I', 'J', 'K'],
    Spring: ['A', 'B', 'C', 'D_long', 'D_short', 'E', 'F', 'G', 'H', 'I', 'J', 'K', 'L']
  },
  '2': {
    Fall: ['A', 'B', 'C', 'D_long', 'D_short', 'E', 'F', 'G', 'H', 'I', 'J', 'K'],
    Winter: ['A', 'B', 'C', 'D_long', 'D_short', 'E', 'F', 'G', 'H', 'I', 'J', 'K', 'L'],
    Spring: ['A', 'B', 'C', 'D_long', 'D_short', 'E', 'F', 'G', 'H', 'I', 'J', 'K', 'L']
  },
  '3+': {
    Fall: CORE_PART_ORDER.slice(),
    Winter: CORE_PART_ORDER.slice(),
    Spring: CORE_PART_ORDER.slice()
  }
};

/** Normalizes a free-text grade into one of the WHEN chart's buckets: K, 1, 2, or 3+ (the permissive default for anything else). */
function corePhonicsGradeBucket_(grade) {
  var g = String(grade || '').trim().toUpperCase();
  if (g === 'K' || g === 'KINDERGARTEN') return 'K';
  var n = parseInt(g, 10);
  if (n === 1) return '1';
  if (n === 2) return '2';
  return '3+';
}

/** Which part IDs are applicable for a given grade/season, per the official WHEN chart. */
function getApplicableCorePhonicsParts(grade, season) {
  var bucket = CORE_PHONICS_AVAILABILITY[corePhonicsGradeBucket_(grade)];
  return (bucket && bucket[season]) || CORE_PART_ORDER.slice();
}

function buildCorePhonicsSummary_(measures) {
  var strengths = [];
  var concerns = [];
  var interventions = [];

  Object.keys(measures).forEach(function(key) {
    var m = measures[key];
    if (m.benchmark_tier === 'Mastery') strengths.push(m.label);
    else if (m.benchmark_tier === 'Strategic' || m.benchmark_tier === 'Intensive') {
      concerns.push(m.label + ' (' + m.benchmark_tier + ': ' + m.raw_score + '/' + m.max_score + ')');
    }
  });

  if (concerns.length > 0) {
    interventions.push(
      'This is a mastery test — students are expected to eventually get all items correct. ' +
      'Areas scored Strategic or Intensive will benefit from targeted, explicit phonics instruction ' +
      'and extensive practice in the specific concepts indicated.'
    );
    interventions.push(
      'Review the student’s individual item errors for patterns (e.g., a specific vowel team or blend) ' +
      'to sharpen instruction — CORE’s Teaching Reading Sourcebook has model lessons for introducing and ' +
      'practicing each sound/spelling, blending, and reading/writing words.'
    );
    if (measures.letter_names_and_sounds && measures.letter_names_and_sounds.benchmark_tier === 'Intensive') {
      interventions.push(
        'Consider administering the CORE Phoneme Segmentation Test (or another phonemic-awareness measure) — ' +
        'weak letter/sound knowledge at this level often has an underlying phonemic-awareness component.'
      );
    }
  }

  return {
    strengths: strengths,
    concerns: concerns,
    interventions: interventions
  };
}

/* ===== Assessments/Dra.gs ===== */
// ============================================================
//  DRA / Guided Reading Level / Basal Level Correlation
//  Source: G:\My Drive\ELC Shared\Database\Developmental Reading
//  Assessment and Guided Reading Level Correlation Chart.pdf
//
//  This is a LEVEL-CONVERSION lookup, not a scored benchmark --
//  there is no "tier" here, just "Guided Reading Level X corresponds
//  to DRA level N, typically read around grade Y." Use it to
//  translate between the different leveling systems schools use,
//  not to flag risk.
//
//  Guided Reading Level is the PRIMARY entry field in this app (per
//  request) -- teachers pick a GRL letter, and the corresponding DRA
//  number is looked up/derived from it for record-keeping and growth
//  trending.
//
//  Every value below is read DIRECTLY off the source chart (re-verified
//  against a full-page render, not just extracted text) -- there is no
//  interpolation anywhere in this table. The source's own column
//  structure groups MULTIPLE Guided Reading Level letters under one
//  shared DRA anchor per grade-level column once DRA levels start
//  spacing out above 3rd grade (e.g. the "4th Grade Levels" column
//  prints a single DRA value of 40 alongside all three of Q, R, and S
//  -- DRA simply doesn't distinguish those three sub-levels any more
//  finely than that at this grade band, consistent with DRA usage
//  tapering off after upper-elementary in practice). Where a letter
//  legitimately appears under two adjacent grade columns (Y under both
//  6th and 7th; Z under both 7th and 8th), both rows are kept for
//  reverse (DRA->GRL) lookup precision, while lookupGrl (the forward,
//  primary direction) always resolves to the first/lower one listed.
// ============================================================

var DRA_GRL_TABLE = [
  { dra: 1,  grl: 'A', grade: 'Kindergarten' },
  { dra: 2,  grl: 'B', grade: 'Kindergarten' },
  { dra: 3,  grl: 'C', grade: 'Kindergarten / 1st Grade' },
  { dra: 4,  grl: 'C', grade: '1st Grade' },
  { dra: 5,  grl: 'D', grade: '1st Grade' },
  { dra: 6,  grl: 'D', grade: '1st Grade' },
  { dra: 8,  grl: 'E', grade: '1st Grade' },
  { dra: 10, grl: 'F', grade: '1st Grade' },
  { dra: 12, grl: 'G', grade: '1st Grade' },
  { dra: 14, grl: 'H', grade: '1st Grade' },
  { dra: 16, grl: 'I', grade: '1st Grade' },
  { dra: 18, grl: 'J', grade: '2nd Grade' },
  { dra: 20, grl: 'K', grade: '2nd Grade' },
  { dra: 24, grl: 'L', grade: '2nd Grade' },
  { dra: 28, grl: 'M', grade: '2nd Grade' },
  { dra: 30, grl: 'N', grade: '3rd Grade (Beginning)' },
  { dra: 34, grl: 'O', grade: '3rd Grade (Middle)' },
  { dra: 38, grl: 'P', grade: '3rd Grade (End)' },
  { dra: 40, grl: 'Q', grade: '4th Grade' },
  { dra: 40, grl: 'R', grade: '4th Grade' },
  { dra: 40, grl: 'S', grade: '4th Grade' },
  { dra: 50, grl: 'T', grade: '5th Grade' },
  { dra: 50, grl: 'U', grade: '5th Grade' },
  { dra: 50, grl: 'V', grade: '5th Grade' },
  { dra: 60, grl: 'W', grade: '6th Grade' },
  { dra: 60, grl: 'X', grade: '6th Grade' },
  { dra: 60, grl: 'Y', grade: '6th Grade' },
  { dra: 70, grl: 'Y', grade: '7th Grade' },
  { dra: 70, grl: 'Z', grade: '7th Grade' },
  { dra: 80, grl: 'Z', grade: '8th Grade' }
];

/** Ordered A-Z (every letter A through Z has an entry). */
var GRL_LETTERS = DRA_GRL_TABLE.map(function(row) { return row.grl; })
  .filter(function(grl, i, arr) { return arr.indexOf(grl) === i; });

/** Primary lookup: given a Guided Reading Level letter, returns its DRA level + grade context. */
function lookupGrl(grlLetter) {
  var match = DRA_GRL_TABLE.filter(function(row) { return row.grl === grlLetter; })[0];
  if (!match) return { grl: grlLetter, dra: null, grade: null, note: 'Unrecognized Guided Reading Level: ' + grlLetter };
  return { grl: match.grl, dra: match.dra, grade: match.grade, note: null };
}

/**
 * Reverse lookup (DRA number -> nearest published GRL at or below it). Kept
 * for reference/display; the app's primary entry point is lookupGrl above.
 */
function lookupDra(draLevel) {
  var sorted = DRA_GRL_TABLE.slice().sort(function(a, b) { return a.dra - b.dra; });
  var match = null;
  for (var i = 0; i < sorted.length; i++) {
    if (sorted[i].dra <= draLevel) match = sorted[i];
    else break;
  }
  if (!match) return { dra: draLevel, grl: null, grade: null, note: 'Below the lowest published DRA level (1).' };
  return { dra: draLevel, grl: match.grl, grade: match.grade, note: null };
}

/** Reduces a source-chart grade string ("3rd Grade (Beginning)", "Kindergarten / 1st Grade") to a normalizeGradeKey_-style key. Compound "X / Y" strings take the first (lower) grade, same convention lookupGrl already uses for duplicate letters. */
function draGradeBandToKey_(gradeStr) {
  if (!gradeStr) return null;
  var first = String(gradeStr).split('/')[0].trim();
  if (first.indexOf('Kindergarten') === 0) return 'K';
  var m = first.match(/\d+/);
  return m ? m[0] : null;
}

/**
 * DRA/GRL has no cut-score chart to benchmark against (see file header) --
 * but the correlation table's own grade-anchor column ("Guided Reading
 * Level J typically reads at 2nd Grade") is real source data, and comparing
 * it to the student's ACTUAL grade at administration is a legitimate,
 * source-grounded reading-level signal, not a fabricated cut score. One
 * grade behind -> Strategic; two or more -> Intensive; at or above grade
 * placement -> no concern flag (null), matching the same convention used
 * for ORF/Lexile scores that meet or exceed their norm.
 */
function draLevelTier_(grlResult, studentGrade) {
  if (!grlResult || grlResult.dra === null) return null;
  var typicalNum = gradeKeyToNum_(draGradeBandToKey_(grlResult.grade));
  var actualNum = gradeKeyToNum_(normalizeGradeKey_(studentGrade));
  if (typicalNum === null || actualNum === null) return null;
  var behindBy = actualNum - typicalNum;
  if (behindBy >= 2) return 'Intensive';
  if (behindBy === 1) return 'Strategic';
  return null;
}

// ============================================================
//  DRA2 Seasonal Benchmarks (Grades K-8)
//  Source: Pearson's own published "DRA2 Benchmark Recommendation
//  for Grades K-8" (support.pearson.com/usclinical/s/article/
//  DRA2-Benchmark-Recommendation-for-Grades-K-8), confirmed via a
//  screenshot of the real page, 2026-10-02. One author-recommended
//  target DRA level per grade/season -- the same single-number
//  convention this app already uses for easyCBM/ORF/Lexile (see
//  getBenchmarkReference_, Registry.gs), not a tiered range -- chosen
//  over Connecticut's own state-adopted Deficient/Proficient range
//  table (also real, also verified) specifically for consistency:
//  Pearson's is the only one of the two that actually covers every
//  grade this app tracks (K-8, not just K-3).
//
//  This is what finally makes a real beginning/middle/end-of-grade
//  comparison possible -- see draLevelTier_'s own header comment
//  above for why that wasn't possible before this source existed.
//
//  Grades 4-8 only publish a Beginning and an End of year figure --
//  no Middle-of-year number exists in the source, so Winter stays
//  genuinely unbenchmarked for those grades (same "don't interpolate"
//  principle as every other table in this app).
//
//  Kindergarten's Beginning-of-year benchmark is Guided Reading Level
//  "A" in the source, which this file's own DRA_GRL_TABLE already
//  equates to DRA 1 -- reused here rather than inventing a separate
//  value, so Beginning and Middle of Kindergarten both land on 1.
// ============================================================
var DRA_SEASONAL_BENCHMARKS = {
  K: { Fall: 1, Winter: 1, Spring: 3 },
  '1': { Fall: 3, Winter: 10, Spring: 16 },
  '2': { Fall: 16, Winter: 20, Spring: 28 },
  '3': { Fall: 28, Winter: 34, Spring: 38 },
  '4': { Fall: 38, Spring: 40 },
  '5': { Fall: 40, Spring: 50 },
  '6': { Fall: 50, Spring: 60 },
  '7': { Fall: 60, Spring: 70 },
  '8': { Fall: 70, Spring: 80 }
};

// Same table, flattened into chronological order -- lets "how many
// checkpoints behind is this reading level" be a simple index
// difference instead of separate grade/season arithmetic. Grade 4+
// Winter has no entry at all (not just a null value), consistent with
// it having no published benchmark.
var DRA_BENCHMARK_CHECKPOINTS_ = (function() {
  var order = ['K', '1', '2', '3', '4', '5', '6', '7', '8'];
  var seasons = ['Fall', 'Winter', 'Spring'];
  var list = [];
  order.forEach(function(grade) {
    seasons.forEach(function(season) {
      var benchmark = DRA_SEASONAL_BENCHMARKS[grade][season];
      if (benchmark !== undefined) list.push({ grade: grade, season: season, benchmark: benchmark });
    });
  });
  return list;
})();

/** Index of (grade, season) in the published checkpoint sequence, or null if that exact grade/season has no published benchmark (Grade 4+ Winter only). */
function draCheckpointIndexFor_(grade, season) {
  var gradeKey = normalizeGradeKey_(grade);
  for (var i = 0; i < DRA_BENCHMARK_CHECKPOINTS_.length; i++) {
    if (DRA_BENCHMARK_CHECKPOINTS_[i].grade === gradeKey && DRA_BENCHMARK_CHECKPOINTS_[i].season === season) return i;
  }
  return null;
}

/**
 * Reverse lookup: the most advanced published checkpoint a DRA number
 * meets or exceeds -- "this reading level is where a student should be
 * at [checkpoint]." Same at-or-below convention as lookupDra's own
 * reverse lookup above, including how a tie (the same benchmark
 * published at the end of one grade and the start of the next, e.g.
 * Grade 2 Spring and Grade 3 Fall both = 28) resolves to the LATER,
 * more advanced checkpoint.
 */
function draCheckpointIndexReached_(draNumber) {
  var matchIndex = null;
  for (var i = 0; i < DRA_BENCHMARK_CHECKPOINTS_.length; i++) {
    if (DRA_BENCHMARK_CHECKPOINTS_[i].benchmark <= draNumber) matchIndex = i;
    else break;
  }
  return matchIndex;
}

/**
 * Real find, 2026-10-02 (administrator's own design review, "don't you
 * need the letter AND number to determine beginning/middle/end of a
 * grade"): compares a DRA number against the Pearson-published
 * checkpoint for the student's ACTUAL grade+season at administration,
 * at CHECKPOINT granularity instead of draLevelTier_'s whole-grade
 * granularity. Same "N behind -> Strategic/Intensive" rule as
 * draLevelTier_, just finer: 1 checkpoint behind -> Strategic, 2+ ->
 * Intensive, at or ahead -> no concern (null).
 *
 * Returns null -- meaning "can't evaluate this way," not "on level" --
 * when the CURRENT grade+season itself has no published checkpoint
 * (Grade 4+ Winter). The caller (Registry.gs's 'dra' score function)
 * falls back to draLevelTier_'s whole-grade comparison for that one gap.
 */
function draSeasonalLevelTier_(draNumber, studentGrade, studentSeason) {
  if (draNumber === null || draNumber === undefined) return null;
  var currentIndex = draCheckpointIndexFor_(studentGrade, studentSeason);
  if (currentIndex === null) return null;
  var reachedIndex = draCheckpointIndexReached_(draNumber);
  var behindBy = reachedIndex === null ? currentIndex + 1 : currentIndex - reachedIndex;
  if (behindBy >= 2) return 'Intensive';
  if (behindBy === 1) return 'Strategic';
  return null;
}

