/* ===== Assessments/Lexile.gs ===== */
// ============================================================
//  Lexile Grade Level Charts
//  Source: G:\My Drive\ELC Shared\Database\Lexile Grade Level
//  Charts.pdf (hub.lexile.com) — percentile norms K-12,
//  Fall/Winter/Spring. Verified via coordinate-based extraction
//  (the original 2-page PDF splits mid-7th-grade; page boundaries
//  do not line up with grade boundaries in the raw text layout).
//  "BR" scores ("Beginning Reader") represent below-0L Lexile
//  measures, e.g. BR400L = 400 points below 0L.
// ============================================================

function lexileToNumber_(str) {
  if (str.indexOf('BR') === 0) {
    return -parseInt(str.replace('BR', '').replace('L', ''), 10);
  }
  return parseInt(str.replace('L', ''), 10);
}

// LEXILE_NORMS[grade][season] = [10th, 25th, 50th, 75th, 90th] percentile scores (raw strings, e.g. "BR400L" or "620L")
var LEXILE_NORMS = {
  K:    { Fall: ['BR400L','BR400L','BR345L','BR195L','BR45L'],  Winter: ['BR400L','BR400L','BR250L','BR100L','60L'],   Spring: ['BR400L','BR310L','BR160L','BR5L','145L'] },
  '1':  { Fall: ['BR400L','BR200L','10L','220L','430L'],        Winter: ['BR325L','BR120L','85L','290L','495L'],       Spring: ['BR235L','BR35L','165L','365L','565L'] },
  '2':  { Fall: ['BR90L','100L','290L','480L','670L'],          Winter: ['BR15L','170L','355L','545L','730L'],         Spring: ['60L','245L','425L','605L','790L'] },
  '3':  { Fall: ['180L','355L','530L','705L','880L'],           Winter: ['245L','415L','590L','760L','930L'],          Spring: ['310L','480L','645L','810L','980L'] },
  '4':  { Fall: ['410L','570L','735L','895L','1055L'],          Winter: ['480L','635L','790L','950L','1105L'],         Spring: ['550L','700L','850L','1005L','1155L'] },
  '5':  { Fall: ['595L','745L','900L','1050L','1205L'],         Winter: ['620L','770L','925L','1075L','1230L'],        Spring: ['645L','795L','950L','1100L','1255L'] },
  '6':  { Fall: ['680L','835L','990L','1140L','1295L'],         Winter: ['700L','855L','1010L','1160L','1315L'],       Spring: ['720L','875L','1030L','1180L','1335L'] },
  '7':  { Fall: ['755L','910L','1060L','1215L','1370L'],        Winter: ['770L','925L','1080L','1230L','1385L'],       Spring: ['790L','940L','1095L','1250L','1405L'] },
  '8':  { Fall: ['815L','970L','1125L','1280L','1430L'],        Winter: ['830L','985L','1140L','1295L','1450L'],       Spring: ['845L','1000L','1155L','1310L','1465L'] },
  '9':  { Fall: ['870L','1025L','1180L','1335L','1490L'],       Winter: ['885L','1040L','1195L','1345L','1500L'],      Spring: ['895L','1050L','1205L','1360L','1515L'] },
  '10': { Fall: ['920L','1075L','1230L','1385L','1540L'],       Winter: ['930L','1085L','1240L','1395L','1550L'],      Spring: ['940L','1095L','1250L','1410L','1565L'] },
  '11': { Fall: ['960L','1115L','1270L','1425L','1585L'],       Winter: ['970L','1130L','1285L','1440L','1595L'],      Spring: ['985L','1140L','1295L','1450L','1605L'] },
  '12': { Fall: ['960L','1115L','1270L','1425L','1585L'],       Winter: ['970L','1130L','1285L','1440L','1595L'],      Spring: ['985L','1140L','1295L','1450L','1605L'] }
};

var LEXILE_PERCENTILES = [10, 25, 50, 75, 90];

// A legitimate Lexile score is always a plain non-negative number, optionally
// "L"-suffixed, optionally "BR"-prefixed for below-0L measures (never a raw
// negative number -- see the file header). Anything else is not a Lexile
// score at all, whatever a free-text entry field let through.
var LEXILE_SCORE_FORMAT_RE = /^(BR)?\d+L?$/i;

/**
 * grade: 'K','1'..'12'. season: 'Fall'|'Winter'|'Spring'.
 * lexileScore: a number (e.g. 620) or a Lexile string (e.g. "620L", "BR100L").
 * Returns { percentile, label, published } — percentile is the highest
 * published percentile the student's score meets or exceeds. `published`
 * distinguishes "this grade/season isn't in the norms table" from
 * "genuinely below the 10th percentile" -- both otherwise return
 * percentile: null, and conflating them would let an unscoreable measure
 * masquerade as a real risk flag (same fix already applied to scoreOrf_).
 *
 * Phase 33b: also guards against a malformed lexileScore (this app's entry
 * form takes it as free text). Previously non-Lexile-shaped input (anything
 * from a typo to injected markup) fell through to lexileToNumber_'s
 * parseInt, which silently returns NaN (or a truncated partial number, e.g.
 * "620abc" -> 620) rather than throwing -- NaN then fails every >= band
 * comparison below, reading exactly like a genuine below-10th-percentile
 * score and getting tiered 'Intensive' by Registry.gs for what was actually
 * just unparseable text. published:false (same mechanism used for an
 * unpublished grade/season) stops a malformed value from ever reaching that
 * false-risk-flag path.
 */
function scoreLexile(grade, season, lexileScore) {
  var norms = LEXILE_NORMS[normalizeGradeKey_(grade)];
  if (!norms || !norms[season]) {
    return { percentile: null, label: null, note: 'No Lexile norms published for grade ' + grade + ', ' + season + '.', published: false };
  }

  var rawStr = String(lexileScore).trim();
  if (typeof lexileScore !== 'number' && !LEXILE_SCORE_FORMAT_RE.test(rawStr)) {
    return { percentile: null, label: null, note: 'Not a recognized Lexile score format: "' + rawStr + '".', published: false };
  }

  var scoreNum = typeof lexileScore === 'number' ? lexileScore : lexileToNumber_(rawStr);
  var bandNums = norms[season].map(lexileToNumber_);

  var matched = null;
  for (var i = LEXILE_PERCENTILES.length - 1; i >= 0; i--) {
    if (scoreNum >= bandNums[i]) { matched = LEXILE_PERCENTILES[i]; break; }
  }

  var label = matched === null
    ? 'Below the 10th percentile'
    : 'At or above the ' + matched + 'th percentile';

  return { percentile: matched, label: label, published: true };
}

