/**
 * Full data-integrity sweep, structured for the weekly email below --
 * reuses the exact same collectors diagnoseMalformedSessionPeriods() logs
 * from, so the manual diagnostic and the emailed summary can never
 * silently disagree with each other.
 */
function runDataIntegritySweep_() {
  requireAdministratorOrTrigger_(); // real find, 2026-09-26 -- runs unattended via sendDataIntegritySweepEmail_'s weekly trigger AND must not be a free unauthenticated endpoint for a real caller
  return {
    malformedSessions: collectMalformedSessions_(),
    orphanedData: collectOrphanedStudentData_(),
    duplicateSessions: collectDuplicateSessionGroups_(),
    dateSeasonIssues: collectDateSeasonIssues_(),
    staleSessions: collectStaleSessionsSummary_(),
    sessionsWithNoResults: collectSessionsWithNoResults_(),
    draSessionsMissingNumber: collectDraSessionsMissingNumber_()
  };
}

/**
 * Phase 39: weekly proactive email summarizing everything the manual
 * diagnostics above can find -- added after the malformed-session/
 * orphaned-data/grade-type-mismatch bugs this phase were all only caught
 * because the principal happened to notice a garbled label or an empty
 * chart. This surfaces the same classes of problem on a schedule instead
 * of only by chance. Purely a report -- never deletes or fixes anything
 * itself (see fixMalformedSessionPeriods/deleteOrphanedStudentData_ for
 * that, both still manual/reviewed steps). Same recipient scoping as
 * sendComplianceAlerts (Compliance.gs) -- getDigestRecipientEmails_
 * (Notifications.gs): ELC staff plus the one configured admin address,
 * not every Staff_Access Administrator -- and gated by the same
 * EMAIL_NOTIFICATIONS_ENABLED kill switch as every other notification in
 * this app.
 */
function sendDataIntegritySweepEmail_() {
  requireStaffOrTrigger_(); // real find, 2026-09-26: runs unattended on a weekly trigger (no signed-in user) AND must not be a free unauthenticated endpoint for a real caller -- see requireStaffOrTrigger_'s own comment
  var report = runDataIntegritySweep_();
  var issueCount = report.malformedSessions.length
    + report.orphanedData.total
    + report.duplicateSessions.length
    + report.dateSeasonIssues.invalidDates.length
    + report.dateSeasonIssues.mismatches.length
    + report.sessionsWithNoResults.length
    + report.draSessionsMissingNumber.length;

  var staffEmails = getDigestRecipientEmails_(); // 2026-09-18: ELC staff + the one configured admin address, not every Staff_Access Administrator -- see that function's own comment (Notifications.gs)

  if (staffEmails.length === 0) {
    console.log('sendDataIntegritySweepEmail_: no ELC/admin recipients found -- skipping email.');
    return;
  }

  var lines = [];
  if (issueCount === 0) {
    lines.push('No data-integrity issues found this week -- Assessment_Sessions, Assessment_Results, and related sheets all look clean.');
  } else {
    lines.push(issueCount + ' potential data-integrity issue(s) found this week:');
    lines.push('');
    if (report.malformedSessions.length > 0) {
      lines.push(report.malformedSessions.length + ' session(s) with a blank school_year or season:');
      report.malformedSessions.forEach(function(b) {
        lines.push('  - ' + b.studentLabel + ', session_id=' + b.session.session_id + ' (' + b.session.assessment_type + ', ' + b.session.administration_date + ')');
      });
      lines.push('  Fix: run diagnoseMalformedSessionPeriods() then fixMalformedSessionPeriods() in the Apps Script editor (Code.gs).');
      lines.push('');
    }
    if (report.orphanedData.total > 0) {
      lines.push(report.orphanedData.total + ' orphaned row(s) tied to a student_id no longer in Students:');
      Object.keys(report.orphanedData.bySheet).forEach(function(sheetName) {
        var entry = report.orphanedData.bySheet[sheetName];
        if (entry.count > 0) lines.push('  - ' + sheetName + ': ' + entry.count + ' row(s)');
      });
      lines.push('  Fix: run diagnoseMalformedSessionPeriods() to review, then set CONFIRM_DELETE_ORPHANED_DATA_ = true and re-run to clean up.');
      lines.push('');
    }
    if (report.duplicateSessions.length > 0) {
      lines.push(report.duplicateSessions.length + ' possible duplicate session group(s) (same student, same assessment type, same date):');
      report.duplicateSessions.forEach(function(g) {
        lines.push('  - ' + g.studentLabel + ' -- ' + g.key);
      });
      lines.push('  Review each on the student\'s profile (Assessment History) before deleting anything -- not every same-day pair is a mistake.');
      lines.push('');
    }
    if (report.dateSeasonIssues.invalidDates.length > 0) {
      lines.push(report.dateSeasonIssues.invalidDates.length + ' session(s) with an unparseable administration_date.');
      lines.push('');
    }
    if (report.dateSeasonIssues.mismatches.length > 0) {
      lines.push(report.dateSeasonIssues.mismatches.length + ' session(s) where the stored season doesn\'t match the actual calendar date:');
      report.dateSeasonIssues.mismatches.forEach(function(m) {
        lines.push('  - ' + m.studentLabel + ', session_id=' + m.session.session_id + ' (' + m.session.assessment_type + ', ' + m.date.toDateString()
          + ' -- stored season="' + m.session.season + '" but the date falls in "' + m.expectedSeason + '")');
      });
      lines.push('  Review on the student\'s profile (Assessment History) and correct the season if it\'s wrong.');
      lines.push('');
    }
    if (report.sessionsWithNoResults.length > 0) {
      lines.push(report.sessionsWithNoResults.length + ' session(s) with zero paired Assessment_Results rows (likely a partial write):');
      report.sessionsWithNoResults.forEach(function(entry) {
        lines.push('  - ' + entry.studentLabel + ', session_id=' + entry.session.session_id + ' (' + entry.session.assessment_type + ', ' + entry.session.administration_date + ')');
      });
      lines.push('  Fix: run findSessionsWithNoResults_() in the Apps Script editor (Code.gs) to review, then delete any genuine phantom session directly from the student\'s Assessment History.');
      lines.push('');
    }
    if (report.draSessionsMissingNumber.length > 0) {
      lines.push(report.draSessionsMissingNumber.length + ' DRA session(s) missing their DRA number (an unrecognized Guided Reading Level was entered):');
      report.draSessionsMissingNumber.forEach(function(entry) {
        lines.push('  - ' + entry.studentLabel + ', session_id=' + entry.session.session_id + ' (' + entry.session.administration_date + ')');
      });
      lines.push('  Fix: run findDraSessionsMissingNumber_() in the Apps Script editor (Code.gs) to review, then re-enter the correct Guided Reading Level on the student\'s profile (Assessment History -> Edit).');
      lines.push('');
    }
    lines.push('Full detail (student names, exact session IDs): run diagnoseMalformedSessionPeriods() from the Apps Script editor (Code.gs) and check the Execution log.');
  }

  // Phase 45: a retention NOTICE, not an "issue" -- deliberately excluded
  // from issueCount above since old data isn't a data-integrity problem.
  // Purely informational: this app never auto-purges, an administrator
  // decides whether anything old actually gets deleted.
  if (report.staleSessions.count > 0) {
    lines.push('');
    lines.push('Retention notice: ' + report.staleSessions.count + ' session(s) are ' + report.staleSessions.cutoffYears
      + '+ years old. Not deleted automatically -- run diagnoseMalformedSessionPeriods() (Code.gs) to review the list, then delete '
      + 'individually from a student\'s Assessment History if an administrator decides to.');
  }

  sendNotificationEmail_({
    audience: 'mixed',
    to: staffEmails.join(','),
    subject: (issueCount === 0 ? 'Weekly Data Check: all clear' : 'Weekly Data Check: ' + issueCount + ' issue(s) found') + ' — ELC Student Assessments',
    body: lines.join('\n')
  });
}

/**
 * One-time setup -- run ONCE from the Apps Script editor (Code.gs, this
 * function) to schedule the weekly data-integrity sweep email above.
 * Safe to re-run: clears any existing trigger for this handler first, so
 * re-running never creates duplicates.
 */
function setupDataIntegritySweepTrigger() {
  requireAdministrator_();
  ScriptApp.getProjectTriggers().forEach(function(t) {
    if (t.getHandlerFunction() === 'sendDataIntegritySweepEmail_') ScriptApp.deleteTrigger(t);
  });
  // Real find, 2026-09-26 (independent code review, "notification system"):
  // moved from hour 6 to hour 9 -- same reasoning as
  // setupDecliningStudentAlertTrigger's (Notifications.gs) own comment.
  // Re-run this function once from the Apps Script editor for the new time
  // to take effect on an already-installed trigger; just pushing this file
  // doesn't move it.
  ScriptApp.newTrigger('sendDataIntegritySweepEmail_').timeBased().onWeekDay(ScriptApp.WeekDay.MONDAY).atHour(9).create();
}

/**
 * Run-from-editor repair (Phase 39k follow-up): the REAL root cause behind
 * the student_id/grade Number-vs-String bug class (fixed at the code level
 * across Coverage/Compliance/Roster/Summary/Dashboard/Growth/Interventions/
 * Requests this phase) is that Google Sheets auto-formats a numeric-looking
 * cell as a Number on read, REGARDLESS of what type was originally
 * written -- so even a client-provided String silently becomes a Number
 * again once it lands in a cell with "Automatic" format. The code-level
 * String() fixes neutralize the practical impact everywhere they're
 * applied, but a NEW field could trip the same bug again as long as these
 * columns stay Automatic-formatted. This sets every student_id/grade-like
 * column, across every sheet that has one, to Plain Text format, then
 * rewrites each EXISTING value as an explicit String -- setNumberFormat
 * alone only changes how FUTURE entries get interpreted, it does not
 * retroactively convert values already sitting in the sheet. Safe to
 * re-run: rewriting an already-text value as a String is a no-op, and
 * re-applying Plain Text format to an already-Plain-Text column is a
 * no-op too.
 */
function fixStudentIdAndGradeColumnFormatting_() {
  requireAdministrator_(); // real find, 2026-09-26 -- destructive, rewrites real sheet data/formatting
  var targets = [
    { sheet: SHEET_STUDENTS, columns: ['student_id', 'grade'] },
    { sheet: SHEET_SESSIONS, columns: ['student_id', 'grade_at_admin'] },
    { sheet: SHEET_RESULTS, columns: ['student_id'] },
    { sheet: SHEET_REQUESTS, columns: ['student_id'] },
    { sheet: SHEET_INTERVENTIONS, columns: ['student_id'] },
    { sheet: SHEET_IEP_EXPORT_LOG, columns: ['student_id'] }
  ];

  var ss = getOrCreateSpreadsheet_();
  var totalChanged = 0;
  targets.forEach(function(target) {
    var sheet = getOrCreateSheet_(ss, target.sheet);
    var headers = SHEET_SCHEMAS[target.sheet];
    var lastRow = sheet.getLastRow();
    if (lastRow < 2) {
      console.log(target.sheet + ': no data rows, nothing to fix.');
      return;
    }
    target.columns.forEach(function(colName) {
      var colIdx = headers.indexOf(colName);
      if (colIdx === -1) {
        console.log(target.sheet + '.' + colName + ': column not found, skipping.');
        return;
      }
      var range = sheet.getRange(2, colIdx + 1, lastRow - 1, 1);
      range.setNumberFormat('@'); // Plain Text -- governs how future entries get interpreted
      var values = range.getValues();
      var changed = 0;
      var rewritten = values.map(function(row) {
        var v = row[0];
        if (v === '' || v === null || v === undefined) return [v];
        if (typeof v !== 'string') changed++;
        return [String(v)];
      });
      range.setValues(rewritten);
      totalChanged += changed;
      console.log(target.sheet + '.' + colName + ': ' + values.length + ' cell(s) checked, ' + changed + ' converted from Number to String.');
    });
  });
  console.log(totalChanged + ' total cell(s) converted. Re-run diagnoseMalformedSessionPeriods() to confirm no lingering type issues.');
}

/**
 * Run-from-editor repair (Phase 39): applies the same school_year/season
 * derivation diagnoseMalformedSessionPeriods() logs, via updateRow_ -- only
 * touches rows where one of those fields is actually blank, deriving from
 * each row's own administration_date (never "today", since the row may be
 * historical). Run diagnoseMalformedSessionPeriods() first to see what
 * this will do before running it.
 */
function fixMalformedSessionPeriods() {
  requireAdministrator_(); // real find, 2026-09-26 -- destructive, rewrites real session data
  var sessions = readAllRows_(SHEET_SESSIONS);
  var bad = sessions.filter(function(s) { return !s.school_year || !s.season; });
  if (bad.length === 0) {
    console.log('No sessions with a blank school_year or season found -- nothing to fix.');
    return;
  }
  bad.forEach(function(s) {
    var patch = {};
    if (!s.school_year) patch.school_year = schoolYearForDate_(s.administration_date);
    if (!s.season) patch.season = seasonForDate_(s.administration_date);
    updateRow_(SHEET_SESSIONS, 'session_id', s.session_id, patch);
    console.log('Fixed session_id=' + s.session_id + ': ' + JSON.stringify(patch));
  });
  console.log(bad.length + ' session(s) corrected.');
}

