/**
 * Phase 25j (Phase 6a review finding): every one-time trigger above can
 * only ever be installed by running its setup function from the Apps
 * Script editor -- there was previously no way to tell, from inside the
 * app itself, whether that had actually been done (listInstalledTriggers()
 * above answers the same question, but only for someone already in the
 * editor, which defeats the point for an administrator just using the
 * web app). Administrator-only, matching everything else on the Staff
 * Access page this is shown alongside.
 */
function getInstalledTriggerStatus() {
  requireAdministrator_();
  var installedHandlers = {};
  ScriptApp.getProjectTriggers().forEach(function(t) { installedHandlers[t.getHandlerFunction()] = true; });
  return sanitizeForClient_(ONE_TIME_SETUP_TRIGGERS.map(function(t) {
    return {
      handler: t.handler, setup_function: t.setupFunction, label: t.label, description: t.description,
      installed: !!installedHandlers[t.handler]
    };
  }));
}

/**
 * Run-from-editor, READ-ONLY diagnostic (2026-09-26, for three reported
 * issues in one pass): for each student matching one of the given first
 * names, prints their ELC Elementary registration + derived serviceAreas +
 * the compliance requirement groups computed FROM that (to check whether a
 * student not registered for a service area is still showing a
 * requirement -- issue: benchmark compliance listing assessments for
 * students not in that ELC class), every Assessment_Sessions row they have
 * (to check whether a CORE Phonics session genuinely exists or is missing
 * -- issue: can't capture Core Phonics data for a prior year), and every
 * Assessment_Results row per session with its raw_score/measure_id/grade/
 * season context (to find exactly which measure a "not benchmarked" result
 * with a specific raw score belongs to -- issue: a score showing "not
 * benchmarked" that looks like it should have a real tier). Changes
 * nothing. Pass a comma-separated list of first names, e.g.
 * diagnoseStudentReportedIssues('Clara,Maisie,Tessa').
 */
function diagnoseStudentReportedIssues(firstNamesCsv) {
  requireAdministrator_(); // real find, 2026-09-26
  if (!firstNamesCsv) { console.log('Pass first names, e.g. diagnoseStudentReportedIssues("Clara,Maisie,Tessa").'); return; }
  var names = firstNamesCsv.split(',').map(function(n) { return n.trim().toLowerCase(); }).filter(Boolean);

  var students = readAllRows_(SHEET_STUDENTS).filter(function(s) {
    return names.indexOf(String(s.first_name || '').trim().toLowerCase()) !== -1;
  });
  if (students.length === 0) { console.log('No student matched any of: ' + names.join(', ')); return; }

  var elcByStudentId = {};
  try {
    getElcElementaryAssignments_().forEach(function(r) { if (r.studentId) elcByStudentId[String(r.studentId)] = r; });
  } catch (e) {
    console.log('ELC Elementary tab unavailable: ' + e.message);
  }

  var sessions = readAllRows_(SHEET_SESSIONS);
  var results = readAllRows_(SHEET_RESULTS);

  students.forEach(function(s) {
    console.log('=== ' + s.first_name + ' ' + s.last_name + ' (student_id=' + s.student_id + ', current grade=' + s.grade + ', active=' + s.active + ') ===');

    var elc = elcByStudentId[String(s.student_id)];
    if (!elc) {
      console.log('  Not on ELC Elementary tab at all -- has NO ongoing compliance requirement (see getComplianceServiceAreasByStudent_, Compliance.gs).');
    } else {
      console.log('  ELC Elementary row: grade=' + elc.grade + ', serviceAreas=' + JSON.stringify(elc.serviceAreas) + ', teacher emails=' + JSON.stringify(elc.emails));
    }
    var gradeKey = complianceGradeKey_(s.grade);
    var groups = complianceRequirementGroupsForStudent_(gradeKey, elc ? elc.serviceAreas : null);
    console.log('  Compliance requirement groups derived from the above: ' + (groups.length ? JSON.stringify(groups.map(function(g) { return g.label; })) : '(none -- correctly not tracked)'));

    var studSessions = sessions.filter(function(sess) { return String(sess.student_id) === String(s.student_id); });
    console.log('  ' + studSessions.length + ' Assessment_Sessions row(s):');
    studSessions.sort(function(a, b) { return new Date(a.administration_date) - new Date(b.administration_date); });
    studSessions.forEach(function(sess) {
      console.log('    session_id=' + sess.session_id + ' type=' + sess.assessment_type + ' school_year=' + sess.school_year
        + ' season=' + sess.season + ' grade_at_admin=' + sess.grade_at_admin + ' admin_date=' + sess.administration_date);
      results.filter(function(r) { return r.session_id === sess.session_id; }).forEach(function(r) {
        console.log('      measure_id=' + r.measure_id + ' raw_score=' + r.raw_score + ' max_score=' + r.max_score + ' benchmark_tier=' + (r.benchmark_tier || '(none)'));
      });
    });
  });
}

/**
 * Run-from-editor diagnostic (2026-09-24, at the school's report of the
 * same compliance email arriving twice a day -- see Email_Log). Real find:
 * getInstalledTriggerStatus/the in-app Trigger Setup page above only ever
 * collapse ScriptApp.getProjectTriggers() into `installedHandlers[handler]
 * = true` -- a boolean that can NEVER reveal a SECOND trigger calling the
 * same handler, only whether at least one exists. That's exactly the kind
 * of duplicate a setup function (e.g. setupComplianceComingDueAlertTriggers)
 * being run more than once would create -- two full trigger installs,
 * each firing independently, both calling the identical handler, a few
 * minutes apart depending on where Apps Script happened to land their
 * randomized time-of-day. This counts triggers per handler instead of
 * just checking presence, so a real duplicate is visible instead of
 * silently invisible to the existing tooling. Read-only -- changes
 * nothing.
 */
function diagnoseTriggerDuplicates() {
  requireAdministrator_(); // real find, 2026-09-26
  var triggers = ScriptApp.getProjectTriggers();
  var byHandler = {};
  triggers.forEach(function(t) {
    var h = t.getHandlerFunction();
    if (!byHandler[h]) byHandler[h] = [];
    byHandler[h].push({ id: t.getUniqueId(), source: t.getTriggerSource() });
  });

  console.log(triggers.length + ' total trigger(s) installed across this whole project.');
  var handlers = Object.keys(byHandler).sort();
  var anyDuplicate = false;
  handlers.forEach(function(h) {
    var entries = byHandler[h];
    var flag = entries.length > 1 ? '  <-- ' + entries.length + ' TRIGGERS for this ONE handler -- it will run ' + entries.length + ' times every time it fires. This is almost certainly why the same email is arriving multiple times.' : '';
    if (entries.length > 1) anyDuplicate = true;
    console.log('  ' + h + ': ' + entries.length + ' trigger(s) (id' + (entries.length > 1 ? 's' : '') + ': ' + entries.map(function(e) { return e.id; }).join(', ') + ')' + flag);
  });

  if (!anyDuplicate) {
    console.log('No duplicate triggers found -- every handler above has exactly one trigger installed. The repeated email has some other cause (worth re-checking sendComplianceComingDueAlerts_\'s dedup key logic, Compliance.gs).');
  } else {
    console.log('To fix: for each flagged handler, run deleteAllTriggersForHandler_("handlerName") once to clear every trigger for it, then run that handler\'s OWN setup function (see ONE_TIME_SETUP_TRIGGERS, Code.gs, for which one) exactly ONCE to reinstall a single clean trigger.');
  }
}

/**
 * Run-from-editor cleanup (2026-09-24) -- deletes EVERY trigger calling
 * `handlerName`, regardless of how many exist. Pass the exact handler
 * function name (e.g. "sendComplianceComingDue14DayAlerts"), not the
 * setup function. After running this, re-run that handler's own setup
 * function (ONE_TIME_SETUP_TRIGGERS, above) exactly once to reinstall a
 * single trigger -- this function only removes, it never reinstalls,
 * since guessing which trigger to "keep" among duplicates is less safe
 * than clearing all of them and reinstalling fresh from the known-correct
 * setup function.
 */
/**
 * Run-from-editor diagnostic (2026-09-24) -- diagnoseTriggerDuplicates
 * ruled out duplicate triggers (exactly one of each), so the compliance
 * "coming up in N days" email repeating DAILY with a new day-count each
 * time must be the dedup guard in sendComplianceComingDueAlerts_
 * (Compliance.gs) not actually blocking a repeat send. That guard is a
 * PropertiesService key ('COMPLIANCE_ALERT_SENT_<school_year>_<season>_
 * <stage>') that should persist across days and permanently block a
 * second send for the same checkpoint/stage once set. This lists every
 * script property whose key starts with that prefix, so it's visible
 * whether the key is even being set/persisted at all, rather than
 * guessing. Read-only.
 */
function diagnoseComplianceAlertDedupKeys() {
  requireAdministrator_(); // real find, 2026-09-26
  var props = PropertiesService.getScriptProperties().getProperties();
  var matches = Object.keys(props).filter(function(k) { return k.indexOf('COMPLIANCE_ALERT_SENT_') === 0; });
  if (matches.length === 0) {
    console.log('No COMPLIANCE_ALERT_SENT_* properties exist at all -- the dedup guard has never successfully recorded a send, which is consistent with it never actually blocking a repeat.');
    return;
  }
  console.log(matches.length + ' COMPLIANCE_ALERT_SENT_* propert(y/ies) currently stored:');
  matches.sort().forEach(function(k) { console.log('  ' + k + ' = ' + props[k]); });
}

function deleteAllTriggersForHandler_(handlerName) {
  requireAdministrator_(); // real find, 2026-09-26 -- deletes live triggers
  var matches = ScriptApp.getProjectTriggers().filter(function(t) { return t.getHandlerFunction() === handlerName; });
  if (matches.length === 0) { console.log('No triggers found for handler "' + handlerName + '" -- nothing to delete.'); return; }
  matches.forEach(function(t) { ScriptApp.deleteTrigger(t); });
  console.log('Deleted ' + matches.length + ' trigger(s) for "' + handlerName + '". Now run its setup function ONCE (see ONE_TIME_SETUP_TRIGGERS, Code.gs) to reinstall a single clean trigger.');
}

