// Who administered the assessment, in role terms -- distinct from the
// administered_by column (the signed-in user's email, captured
// automatically for audit purposes and never shown in the UI). This one is
// a manual, required choice so history/exports can distinguish a
// grade-level teacher's administration from an ELC pull-out session.
var ADMINISTRATOR_ROLES = ['Grade-Level Teacher', 'ELC Staff', 'Other'];

/** Client helper: the fixed list of administrator-role choices for the New Assessment form's dropdown. */
function getAdministratorRoles() {
  requireStaff_();
  return sanitizeForClient_(ADMINISTRATOR_ROLES);
}

// ── Client-callable endpoints ───────────────────────────────
// (getRoster, getStudent, addManualStudent live in Roster.gs;
//  getAssessmentTypes lives in Registry.gs;
//  getStudentHistory lives in Growth.gs)

/**
 * Phase 35 (performance): opening a student's profile used to cost several
 * sequential google.script.run round trips (Index.html's loadStudent_) --
 * each its own Apps Script execution, each independently re-deriving the
 * caller's access scope and each separately calling getStudent() (a full
 * Students-sheet scan). Bundles them into one round trip. Deliberately
 * calls the real functions unchanged (not a rewritten shortcut), so
 * authorization/behavior is identical to calling them separately -- if any
 * would have thrown (e.g. an out-of-scope student), this throws the same
 * way, since nothing here swallows errors.
 *
 * Phase 45 (2026-08-04): dropped getStudentInterventions -- the
 * Interventions.gs support/intervention log was removed at the user's
 * request (accommodations/modifications cover this now; formal
 * interventions are tracked through the IEP process outside this tool).
 */
function getStudentProfileBundle(studentId) {
  return {
    history: getStudentHistory(studentId),
    requests: getRequestsForStudent(studentId),
    iepGoals: getStudentIepGoals(studentId),
    accommodations: getStudentAccommodations(studentId),
    section504: getSection504Plan(studentId)
  };
}

/**
 * Live "what would the Composite calculate to" preview -- lets a teacher
 * see the auto-calculated Composite (and its tier) as soon as every
 * required measure is filled in, without saving first (2026-09-17, at the
 * school's request: "is there a way for it to appear before saving").
 * Read-only, never writes anything. Reuses computeDibelsComposite/
 * scoreDibels directly (Assessments/Dibels.gs) -- the exact same formula
 * submitSession/updateSessionFields use when actually saving, so this
 * preview can never drift out of sync with what gets recorded.
 */
function previewDibelsComposite(grade, season, rawScoresByMeasure, administrationDate) {
  requireStaff_();
  // Real find (2026-09-22): this used to score straight against the raw
  // `season` -- for 'Other' that always meant a blank/tierless preview,
  // even though the actual save (submitSession/updateSessionFields, via
  // ASSESSMENT_REGISTRY.dibels.score) estimates a real season from the
  // administration date and shows a genuine tier. Mismatched preview vs.
  // save was itself the confusing part the school flagged -- resolving the
  // same way here keeps what's typed in sync with what gets saved.
  var benchmarkSeason = resolveBenchmarkSeason_(season, administrationDate).season;
  var calc = computeDibelsComposite(grade, benchmarkSeason, rawScoresByMeasure || {});
  if (calc.composite === null) {
    return sanitizeForClient_({
      composite: null,
      missing_labels: (calc.missing || []).map(function(m) { return (DIBELS_MEASURES[m] || {}).label || m; })
    });
  }
  var result = scoreDibels('COMPOSITE', grade, benchmarkSeason, calc.composite);
  return sanitizeForClient_({ composite: calc.composite, tier: result.tier, missing_labels: [] });
}

/**
 * Writes one session's ACTUAL result rows from a freshly-scored `measures`
 * map (Registry.gs's scoreAssessmentSession output) -- shared by
 * submitSession (a brand new session) and updateSessionMeasures (correcting
 * an existing one), so both stay behind the exact same filtering rule.
 *
 * Real find (2026-09-17, Rowan Calloway case): a DIBELS session missing
 * enough measures to auto-calculate the Composite gets a placeholder entry
 * in scored.measures.composite (raw_score: null, benchmark_tier: null,
 * meaning: "Enter all required measures...") -- see the dibels branch of
 * ASSESSMENT_REGISTRY (Registry.gs) and its Phase 36 finding #04 comment.
 * That placeholder exists ONLY to explain, on the immediate results
 * screen, why no composite was scored -- it carries no actual measurement.
 * This used to get written to Assessment_Results as a real, permanent row
 * anyway (every key in scored.measures, no filter), which meant a
 * student's history could carry a phantom "Composite" data point with no
 * score and no tier -- and Growth.gs's getStudentHistory/Index.html's
 * report builders then had no way to tell that apart from a genuinely
 * GOOD untiered result (e.g. Lexile meeting benchmark), rendering it as
 * "Meeting expectations" even when the student's real, most recent
 * tiered concern was Red. Filtering to only measures that were ACTUALLY
 * scored (raw_score present) before writing fixes this at the source;
 * the placeholder's explanatory `meaning` is still returned to the
 * client directly from `measures`, so the immediate "why no composite"
 * feedback is unaffected.
 */
function writeScoredResults_(sessionId, studentId, assessmentType, measures) {
  var scoredMeasureIds = Object.keys(measures).filter(function(measureId) {
    var m = measures[measureId];
    return m.raw_score !== null && m.raw_score !== undefined;
  });

  // Phase 35 #5 (performance): one batched multi-row write for every
  // measure instead of a separate appendRow_ call per measure -- a
  // 5-measure CORE Phonics session used to be 5 Sheets API round trips
  // just for its results, now it's 1. See appendRows_ (Data.gs).
  var resultRows = scoredMeasureIds.map(function(measureId) {
    var m = measures[measureId];
    return {
      result_id: Utilities.getUuid(),
      session_id: sessionId,
      student_id: studentId,
      assessment_type: assessmentType,
      measure_id: measureId,
      raw_score: m.raw_score,
      max_score: m.max_score,
      benchmark_tier: m.benchmark_tier,
      item_detail_json: m.item_detail ? JSON.stringify(m.item_detail) : ''
    };
  });
  appendRows_(SHEET_RESULTS, resultRows); // no-op if resultRows is empty (see appendRows_, Data.gs)
}

/**
 * Scores and permanently records one completed assessment administration.
 *
 * payload: {
 *   student_id, assessment_type, administration_date, school_year,
 *   grade_at_admin, season, input: { ...assessment-type-specific fields },
 *   fulfilling_request_id: optional — closes out a pending Assessment_Requests row
 * }
 */
function submitSession(payload) {
  requireStaff_();

  if (!payload || !payload.student_id || !payload.assessment_type) {
    throw new Error('student_id and assessment_type are required.');
  }
  // Real find (2026-09-22, at the school's request): administration_date
  // used to be optional here and silently defaulted to "whenever this was
  // submitted" a few lines below -- which could quietly record the WRONG
  // date for a test actually given earlier (or entered late in the day).
  // The client already makes this a required field (collectAndSubmit,
  // Index.html), but that's only ever a UX nicety -- this is the actual
  // enforcement point, since a client-side check alone can't be trusted.
  if (!payload.administration_date) {
    throw new Error('administration_date is required.');
  }
  if (ADMINISTRATOR_ROLES.indexOf(payload.administrator_role) === -1) {
    throw new Error('administrator_role must be one of: ' + ADMINISTRATOR_ROLES.join(', '));
  }
  // Confirms the student actually exists (and throws a clear error otherwise)
  // before anything is written -- getStudent() itself logs by student_id
  // only, never a name, if the lookup fails. Kept (not discarded) since the
  // grade/year mismatch check right below needs the student's CURRENT grade.
  var student = getStudent(payload.student_id);
  if (!ASSESSMENT_REGISTRY[payload.assessment_type]) {
    throw new Error('Unknown assessment_type: ' + payload.assessment_type);
  }

  // Real find (2026-09-10): nothing previously caught a "Grade at
  // administration" that doesn't match the School year selected for a NEW
  // session -- a stale/uncorrected default (client-side onSchoolYearChanged_,
  // Index.html, now recalculates a suggestion, but nothing stopped someone
  // overriding it wrong), or a plain data-entry mistake, previously saved
  // completely silently. That's exactly what produced the real corrupted
  // session history GradeAudit.gs was built to find and clean up. Same
  // warn-not-block pattern as the duplicate-session check right below --
  // a genuine retention (a student actually repeating a grade) is a
  // legitimate reason for these not to match, so only a human who knows
  // the student can tell the two apart.
  if (!payload.confirm_grade_year_mismatch) {
    var gradeYearMismatch = findGradeYearMismatch_(student, payload.school_year, payload.grade_at_admin);
    if (gradeYearMismatch) {
      return sanitizeForClient_({
        grade_year_mismatch_warning: true,
        expected_grade: gradeYearMismatch.expected_grade,
        entered_grade: gradeYearMismatch.entered_grade
      });
    }
  }

  // Nothing previously caught an accidental double-entry (e.g. a page
  // reload/double-tap re-submitting the same screening, or a second person
  // administering a test someone already gave this period without checking
  // first). Skip the check on the resubmit once the client has already
  // shown the teacher the existing session and they chose to proceed
  // anyway (payload.confirm_duplicate) -- this is a warn-not-block gate,
  // since a genuine re-administration this period is a real use case.
  if (!payload.confirm_duplicate) {
    var duplicate = findDuplicateSession_(payload);
    if (duplicate) {
      return sanitizeForClient_({
        duplicate_warning: true,
        existing_session: {
          session_id: duplicate.session_id,
          administration_date: duplicate.administration_date
        }
      });
    }
  }

  // 2026-09-22: lets ASSESSMENT_REGISTRY's per-type score() functions
  // resolve an 'Other' season to its nearest real benchmark window from
  // the actual calendar date (see resolveBenchmarkSeason_, Registry.gs) --
  // administration_date itself is guaranteed present by the required-field
  // check above, so this is never blank.
  payload.input = payload.input || {};
  payload.input.administrationDate = payload.administration_date;
  // 2026-09-22, at the school's request: see ASSESSMENT_REGISTRY.easycbm_math.score
  // (Registry.gs) for what this does. Only ever set by the client for
  // easycbm_math; harmless no-op for every other assessment_type since
  // their score() functions never look at input.testGrade.
  if (payload.test_grade_level) payload.input.testGrade = payload.test_grade_level;
  var scored = scoreAssessmentSession(payload.assessment_type, payload.input);

  // Real find continuation (2026-09-17, Rowan Calloway case): missing enough
  // measures to auto-calculate the DIBELS Composite used to save silently,
  // with the only sign anything was wrong a small muted note buried in the
  // results table AFTER saving -- easy to miss, and the teacher had already
  // moved on to the next student by then. Same warn-not-block pattern as
  // the grade/year-mismatch and duplicate-session checks above: block the
  // save and tell them exactly what's missing, unless they've already
  // confirmed once and want to proceed without it (a real, if less common,
  // case -- e.g. a discontinued/gated administration where those measures
  // genuinely won't be given).
  if (payload.assessment_type === 'dibels' && !payload.confirm_incomplete_composite) {
    var compositeMeasure = scored.measures.composite;
    if (compositeMeasure && compositeMeasure.raw_score === null && compositeMeasure.missing && compositeMeasure.missing.length > 0) {
      return sanitizeForClient_({
        composite_incomplete_warning: true,
        missing_measures: compositeMeasure.missing.map(function(m) { return (DIBELS_MEASURES[m] || {}).label || m; })
      });
    }
  }

  var sessionId = Utilities.getUuid();
  var administeredBy = Session.getActiveUser().getEmail();
  // Phase 39: a blank school_year/season used to get written as '', which
  // makes Dashboard.gs build a period key like "2026-2027 (no season)" --
  // that fallback label then broke the space-delimited period-key parsing
  // used to render trend labels (garbled "This Month" text, a phantom
  // zero-count trend bar). Both fields are always derivable from the
  // administration date (required above, 2026-09-22 -- no longer just a
  // fallback default), so default to that instead of ever persisting a
  // blank value -- whatever client path omitted them (a bug there, not
  // something this endpoint should trust).
  var administrationDate = payload.administration_date;
  var schoolYear = payload.school_year || schoolYearForDate_(administrationDate);
  var season = payload.season || seasonForDate_(administrationDate);

  // Sheets writes aren't transactional -- if something throws partway through
  // (a transient API error, the 6-minute execution cap, a bad measure value),
  // log which step got to and how far, identified by session_id only (never
  // student name), so a partial write is at least diagnosable/reconcilable
  // rather than silently leaving orphaned data with no trace.
  try {
    appendRow_(SHEET_SESSIONS, {
      session_id: sessionId,
      student_id: payload.student_id,
      assessment_type: payload.assessment_type,
      administration_date: administrationDate,
      school_year: schoolYear,
      grade_at_admin: payload.grade_at_admin || '',
      season: season,
      administered_by: administeredBy,
      summary_json: JSON.stringify(scored.summary),
      created_at: new Date(),
      notes: String(payload.notes || '').substring(0, 2000),
      administrator_role: payload.administrator_role,
      test_grade_level: payload.test_grade_level || ''
    });

    writeScoredResults_(sessionId, payload.student_id, payload.assessment_type, scored.measures);

    if (payload.fulfilling_request_id) {
      fulfillRequest_(payload.fulfilling_request_id, sessionId);
    }
  } catch (e) {
    console.error('submitSession failed partway for session_id ' + sessionId + ': ' + e.message);
    throw e;
  }

  return sanitizeForClient_({ session_id: sessionId, measures: scored.measures, summary: scored.summary });
}

/**
 * Compares a NEW session's (school_year, grade_at_admin) against what's
 * expected given the student's CURRENT grade -- stepping it backward one
 * level per school year between now and the entered year (same reverse
 * calculation as GradeAudit.gs's stepGradeBack_/schoolYearStartYear_ and
 * Index.html's client-side mirror, onSchoolYearChanged_). Returns null
 * when there's nothing to confidently compare (a blank/future/unrecognized
 * school year, or no expected grade derivable), never a hard failure --
 * this is meant to warn, not block, since a genuine retention looks
 * identical to a real mistake on paper.
 */
function findGradeYearMismatch_(student, schoolYear, enteredGrade) {
  if (!student || !schoolYear || !enteredGrade) return null;
  var currentStart = schoolYearStartYear_(schoolYearForDate_(new Date()));
  var enteredStart = schoolYearStartYear_(schoolYear);
  if (currentStart === null || enteredStart === null) return null;
  var yearsBack = currentStart - enteredStart;
  if (yearsBack < 0) return null; // a future/unrecognized year -- nothing sensible to compare against

  var expected = stepGradeBack_(student.grade, yearsBack);
  if (!expected) return null;

  var entered = normalizeGradeKey_(enteredGrade);
  if (entered === expected) return null;

  return { expected_grade: expected, entered_grade: entered };
}

/**
 * A session counts as a duplicate of another if it's the same student, same
 * assessment type, same school year, and same season -- i.e. it looks like
 * the same screening being entered twice, not a legitimate second
 * administration in a later window. Requires both school_year and season to
 * be present to compare; either being blank means there's nothing reliable
 * to match on, so it's treated as not-a-duplicate rather than guessing.
 */
function findDuplicateSession_(payload) {
  if (!payload.school_year || !payload.season) return null;
  var matches = readAllRows_(SHEET_SESSIONS).filter(function(s) {
    return String(s.student_id) === String(payload.student_id) &&
      s.assessment_type === payload.assessment_type &&
      s.school_year === payload.school_year &&
      s.season === payload.season;
  });
  return matches.length ? matches[matches.length - 1] : null;
}

/**
 * Permanently removes a mis-entered session and its result rows. This is a
 * genuine delete (not a soft-delete like deactivateStudent) -- a wrongly
 * scored or wrong-student session isn't real assessment history worth
 * preserving, it's a data-entry mistake, and correcting it today otherwise
 * requires editing the raw spreadsheet directly. The intended recovery flow
 * is delete-then-re-administer via the normal New Assessment form, so this
 * doesn't need to re-implement submitSession's scoring/validation logic.
 */
function deleteSession(sessionId) {
  var actorEmail = requireStaff_();
  if (!sessionId) throw new Error('session_id is required.');
  var existing = readAllRows_(SHEET_SESSIONS).filter(function(s) { return s.session_id === sessionId; })[0];
  if (!existing) throw new Error('Session not found: ' + sessionId);
  getStudent(existing.student_id); // enforces Phase 15 scope, throws "Student not found" if out of scope

  // Real find, 2026-10-02: captured BEFORE deleting -- once these rows are
  // gone, this audit entry (logAssessmentAudit_, below) is the only
  // remaining record of what they were.
  var deletedResults = readAllRows_(SHEET_RESULTS).filter(function(r) { return r.session_id === sessionId; });

  deleteRows_(SHEET_RESULTS, function(r) { return r.session_id === sessionId; });
  deleteRows_(SHEET_SESSIONS, function(s) { return s.session_id === sessionId; });

  logAssessmentAudit_(actorEmail, 'delete', existing,
    'Deleted session: ' + JSON.stringify(existing) + ' -- results: ' + JSON.stringify(deletedResults));

  return sanitizeForClient_({ deleted: true, session_id: sessionId });
}

/**
 * Corrects a session's METADATA -- administration_date, school_year,
 * season, grade_at_admin, administrator_role, notes -- and (2026-09-17, at
 * the school's request) optionally its ACTUAL SCORES too, via patch.input.
 *
 * Real find (2026-09-17): a wrong or MISSING score used to require
 * delete-then-re-administer (see deleteSession above) -- but that mints a
 * brand-new session_id, losing continuity with the original
 * administration, and can trip findDuplicateSession_ on re-save. That's a
 * poor fit for the common real case (Rowan Calloway): one measure (Oral
 * Reading Fluency — Accuracy) was simply left blank and just needs to be
 * added to the SAME session, not redone from scratch. patch.input, when
 * provided, is the exact same shape scoreAssessmentSession expects for
 * this assessment_type (e.g. DIBELS' {grade, season, entries: [{measure,
 * rawScore}]}) -- re-runs the identical scoring pipeline submitSession
 * uses, replaces every existing Assessment_Results row for this session
 * (old ones deleted first, not merged, so a score that was cleared out on
 * the edit form doesn't linger), and updates summary_json to match. Runs
 * the same DIBELS-composite-incomplete warn-not-block check submitSession
 * uses (see writeScoredResults_'s own comment for why that placeholder
 * must never become a permanent row).
 *
 * Metadata-only edits (patch.input omitted) behave exactly as before.
 * Same requireStaff_ gate as deleteSession -- there's no reason editing a
 * session should require MORE privilege than the fully destructive delete
 * already allows any staff member to do today.
 *
 * Real find (2026-09-15): this is exactly the same kind of edit that
 * caused the whole grade_at_admin corruption GradeAudit.gs was built to
 * find and clean up (Grade at Administration silently not matching
 * School year). Runs the identical findGradeYearMismatch_ warn-not-block
 * check submitSession already uses, so correcting one field here can't
 * quietly reintroduce that exact class of bug through a different door.
 */
function updateSessionFields(sessionId, patch) {
  var actorEmail = requireStaff_();
  if (!sessionId) throw new Error('session_id is required.');
  var existing = readAllRows_(SHEET_SESSIONS).filter(function(s) { return s.session_id === sessionId; })[0];
  if (!existing) throw new Error('Session not found: ' + sessionId);
  var student = getStudent(existing.student_id); // enforces Phase 15 scope, throws "Student not found" if out of scope

  patch = patch || {};
  if (patch.administrator_role && ADMINISTRATOR_ROLES.indexOf(patch.administrator_role) === -1) {
    throw new Error('administrator_role must be one of: ' + ADMINISTRATOR_ROLES.join(', '));
  }

  var newSchoolYear = patch.school_year || existing.school_year;
  var newGrade = patch.grade_at_admin || existing.grade_at_admin;
  if (!patch.confirm_grade_year_mismatch) {
    var gradeYearMismatch = findGradeYearMismatch_(student, newSchoolYear, newGrade);
    if (gradeYearMismatch) {
      return sanitizeForClient_({
        grade_year_mismatch_warning: true,
        expected_grade: gradeYearMismatch.expected_grade,
        entered_grade: gradeYearMismatch.entered_grade
      });
    }
  }

  var scored = null;
  if (patch.input) {
    patch.input.administrationDate = patch.administration_date || existing.administration_date;
    // Same preservation-fallback pattern as existingOrfAccuracy/existingMaze:
    // an edit that doesn't touch the Test Grade Level field (e.g. fixing an
    // unrelated typo in the notes) must not silently drop a previously-set
    // override, since editing always re-scores from scratch.
    var effectiveTestGrade = patch.test_grade_level !== undefined ? patch.test_grade_level : existing.test_grade_level;
    if (effectiveTestGrade) patch.input.testGrade = effectiveTestGrade;
    scored = scoreAssessmentSession(existing.assessment_type, patch.input);
    if (existing.assessment_type === 'dibels' && !patch.confirm_incomplete_composite) {
      var compositeMeasure = scored.measures.composite;
      if (compositeMeasure && compositeMeasure.raw_score === null && compositeMeasure.missing && compositeMeasure.missing.length > 0) {
        return sanitizeForClient_({
          composite_incomplete_warning: true,
          missing_measures: compositeMeasure.missing.map(function(m) { return (DIBELS_MEASURES[m] || {}).label || m; })
        });
      }
    }
  }

  var fields = {};
  if (patch.administration_date) fields.administration_date = patch.administration_date;
  if (patch.school_year) fields.school_year = patch.school_year;
  if (patch.season) fields.season = patch.season;
  if (patch.grade_at_admin) fields.grade_at_admin = patch.grade_at_admin;
  if (patch.administrator_role) fields.administrator_role = patch.administrator_role;
  if (patch.notes !== undefined) fields.notes = String(patch.notes || '').substring(0, 2000);
  if (patch.test_grade_level !== undefined) fields.test_grade_level = patch.test_grade_level;
  if (scored) fields.summary_json = JSON.stringify(scored.summary);

  updateRow_(SHEET_SESSIONS, 'session_id', sessionId, fields);

  if (scored) {
    // Real find, 2026-09-26: this used to delete the old Assessment_Results rows
    // then write the new ones with no try/catch -- if the write threw partway
    // (transient Sheets API error, the 6-minute execution cap), the old scores
    // were already gone and the new ones never landed, leaving the session with
    // zero results and summary_json describing measures that don't exist
    // anywhere. Now the old rows are captured first and restored on failure,
    // and the failure is surfaced with the session ID instead of silently
    // returning "updated: true".
    var oldResultRows = readAllRows_(SHEET_RESULTS).filter(function(r) { return r.session_id === sessionId; });
    deleteRows_(SHEET_RESULTS, function(r) { return r.session_id === sessionId; });
    try {
      writeScoredResults_(sessionId, existing.student_id, existing.assessment_type, scored.measures);
    } catch (e) {
      try {
        appendRows_(SHEET_RESULTS, oldResultRows);
      } catch (restoreError) {
        console.error('updateSessionFields: FAILED TO RESTORE old Assessment_Results rows for session ' + sessionId + ' after a failed re-score -- ' + restoreError.message + ' -- this session now has ZERO results and needs manual recovery.');
      }
      throw new Error('Failed to save updated scores for session ' + sessionId + ': ' + e.message + ' (previous scores were restored).');
    }
  }

  // Real find, 2026-10-02 (administrator-requested feature): records WHO
  // changed an already-saved session, WHEN, and WHAT actually changed --
  // only the metadata fields that genuinely differ from before, plus a
  // summary of the new scores whenever patch.input re-scored the session.
  var auditChanges = [];
  Object.keys(fields).forEach(function(key) {
    if (key === 'summary_json') return; // internal derived field, not itself a meaningful change to log
    var oldVal = existing[key] == null ? '' : existing[key];
    var newVal = fields[key] == null ? '' : fields[key];
    if (String(oldVal) !== String(newVal)) auditChanges.push(key + ': "' + oldVal + '" -> "' + newVal + '"');
  });
  if (scored) {
    auditChanges.push('scores re-entered: ' + Object.keys(scored.measures).map(function(k) {
      return k + '=' + scored.measures[k].raw_score;
    }).join(', '));
  }
  if (auditChanges.length > 0) logAssessmentAudit_(actorEmail, 'edit', existing, auditChanges.join('; '));

  return sanitizeForClient_({
    updated: true,
    session_id: sessionId,
    measures: scored ? scored.measures : undefined,
    summary: scored ? scored.summary : undefined
  });
}

/**
 * Every item_detail_json already on file for one session, parsed and
 * keyed by measure_id (e.g. {part_a: [true, false, ...], dra_level: "M"}).
 * getStudentHistory (Growth.gs) deliberately doesn't carry this for every
 * point returned to the client (it's only meaningful for CORE Phonics'
 * per-item marks and DRA's original Guided Reading Level letter, and
 * would bloat every other assessment type's response for no reason) --
 * this is the dedicated, on-demand fetch used only when the session Edit
 * form actually needs to pre-fill those two types' score-editing fields
 * (renderCorePhonicsEditFields_/renderDraScoreEditFields_, Index.html).
 * Read-only, same scope enforcement as every other session-scoped
 * endpoint.
 */
function getSessionItemDetail(sessionId) {
  requireStaff_();
  if (!sessionId) throw new Error('session_id is required.');
  var session = readAllRows_(SHEET_SESSIONS).filter(function(s) { return s.session_id === sessionId; })[0];
  if (!session) throw new Error('Session not found: ' + sessionId);
  getStudent(session.student_id); // enforces Phase 15 scope, throws "Student not found" if out of scope

  var byMeasure = {};
  readAllRows_(SHEET_RESULTS).filter(function(r) { return r.session_id === sessionId; }).forEach(function(r) {
    if (!r.item_detail_json) return;
    try {
      byMeasure[r.measure_id] = JSON.parse(r.item_detail_json);
    } catch (e) {
      console.error('getSessionItemDetail: malformed item_detail_json for session_id ' + sessionId + ', measure_id ' + r.measure_id);
    }
  });
  return sanitizeForClient_(byMeasure);
}

/* ===== Data.gs ===== */
// ============================================================
//  ELC Student Assessments — Data Layer
//  Owns the backing spreadsheet: creation, sheet/tab bootstrap,
//  and generic header-mapped row read/write helpers used by
//  every other module. No PII-specific logic lives here — see
//  Roster.gs for that.
// ============================================================

var SPREADSHEET_NAME = 'ELC Student Assessments — Data';
var SPREADSHEET_ID_PROP = 'STUDENT_ASSESSMENTS_SPREADSHEET_ID';

var SHEET_STUDENTS = 'Students';
var SHEET_SESSIONS = 'Assessment_Sessions';
var SHEET_RESULTS = 'Assessment_Results';
var SHEET_ACCESS = 'Staff_Access';
var SHEET_REQUESTS = 'Assessment_Requests';
var SHEET_AUDIT_LOG = 'Access_Audit_Log';
var SHEET_IEP_EXPORT_LOG = 'Iep_Export_Log';
var SHEET_INTERVENTIONS = 'Interventions';
var SHEET_IEP_GOALS = 'Iep_Goals';
var SHEET_ACCOMMODATIONS = 'Accommodations_Modifications';
var SHEET_504_PLANS = 'Section_504_Plans';
var SHEET_504_HISTORY = 'Section_504_History';
var SHEET_EMAIL_LOG = 'Email_Log';
// Real find, 2026-09-27 (administrator-requested feature, "end-of-year
// archival"): a permanent, unchanging record of each student's standing at
// the end of a school year, taken right before Year Rollover bumps grades
// (see bulkAdvanceGrades, Roster.gs). Deliberately a real snapshot (final
// tier + score per measure, not just a pointer to "go look at the live
// history") -- if a score is corrected later, the live history changes to
// reflect that correction, but the archived record must not, since its
// whole purpose is protecting what the official end-of-year picture looked
// like at the time, for board/accountability records.
var SHEET_YEAR_END_ARCHIVE = 'Year_End_Archive';

// Real find, 2026-10-02 (administrator-requested feature, "who/when/what
// made changes to any existing assessment data so it can't be changed
// without a record"): editing (updateSessionFields) or deleting
// (deleteSession) an assessment session that's already saved previously
// left ZERO trace of the original values -- unlike Staff_Access changes,
// which Access_Audit_Log has covered since Phase 21. Administrator-only to
// view (see getAssessmentAuditLog_, Code.gs); any staff member can still
// edit/delete a session (same privilege level as before), but every such
// change is now permanently recorded, visible or not.
var SHEET_ASSESSMENT_AUDIT_LOG = 'Assessment_Audit_Log';

var SHEET_SCHEMAS = {};
SHEET_SCHEMAS[SHEET_ACCESS] = ['email', 'added_date', 'notes', 'access_role', 'scope_grades'];
// Phase 21: who changed whose access, when, and what changed -- see
// logAccessAudit_ in Code.gs. Self-provisions on first write via
// getOrCreateSheet_, same as every other schema-driven tab.
SHEET_SCHEMAS[SHEET_AUDIT_LOG] = ['timestamp', 'actor_email', 'action', 'target_email', 'details'];
// Phase 31i: every IEP-meeting/parent-handout export -- the one place a
// student's full last name leaves this app (clipboard copy or print) -- is
// logged here, same self-provisioning pattern as SHEET_AUDIT_LOG. See
// logIepExport_ in Code.gs.
SHEET_SCHEMAS[SHEET_IEP_EXPORT_LOG] = ['timestamp', 'actor_email', 'student_id', 'export_type'];
// Phase 46 (2026-10-02): who/when/what changed on an EXISTING assessment
// session -- see logAssessmentAudit_ in Code.gs. `details` carries the
// actual before/after field diff (edit) or a full snapshot of what was
// removed (delete), since a delete leaves nothing else to recover it from.
SHEET_SCHEMAS[SHEET_ASSESSMENT_AUDIT_LOG] = ['timestamp', 'actor_email', 'action', 'student_id', 'session_id', 'assessment_type', 'details'];
SHEET_SCHEMAS[SHEET_REQUESTS] = [
  'request_id', 'student_id', 'assessment_type', 'requested_by', 'requested_at',
  'status', 'note', 'fulfilled_session_id', 'fulfilled_at', 'concern_areas',
  'overdue_alert_sent'
];
SHEET_SCHEMAS[SHEET_STUDENTS] = [
  'student_id', 'first_name', 'last_name', 'grade', 'school',
  'elc_status', 'source', 'active', 'date_added', 'notes', 'deactivation_reason'
];
SHEET_SCHEMAS[SHEET_SESSIONS] = [
  'session_id', 'student_id', 'assessment_type', 'administration_date',
  'school_year', 'grade_at_admin', 'season', 'administered_by',
  'summary_json', 'created_at', 'notes', 'administrator_role',
  // 2026-09-22, at the school's request: when a student can't attempt their
  // OWN grade's easyCBM Math test and is given a lower grade's test
  // instead, grade_at_admin must stay the student's real current grade
  // (roster/compliance/GradeAudit all depend on that meaning what it
  // always has) -- this is a separate, optional field for which grade's
  // benchmark table the entered scores should actually be looked up
  // against. Blank means "same as grade_at_admin," the normal case. See
  // ASSESSMENT_REGISTRY.easycbm_math.score (Registry.gs).
  'test_grade_level'
];
SHEET_SCHEMAS[SHEET_RESULTS] = [
  'result_id', 'session_id', 'student_id', 'assessment_type', 'measure_id',
  'raw_score', 'max_score', 'benchmark_tier', 'item_detail_json'
];
// Phase 23c: a support/intervention log, separate from Assessment_Sessions --
// tracks whether/what help a student is actually getting, not another
// scored measure. See Interventions.gs.
SHEET_SCHEMAS[SHEET_INTERVENTIONS] = [
  'intervention_id', 'student_id', 'type', 'status', 'start_date',
  'end_date', 'notes', 'created_by', 'created_at'
];
// Phase 6i: a formal, legally-documented IEP objective -- distinct from
// Interventions above (an instructional support/strategy). school_year is
// derived once at creation from entered_date (same clock every other
// school-year filter in this app already uses), not the IEP's own annual-
// review date, which this app doesn't track. revised_from_goal_id links a
// goal opened by reviseIepGoal_ back to the goal it replaced, so a rewrite
// preserves the old wording as history instead of overwriting it -- see
// IepGoals.gs.
SHEET_SCHEMAS[SHEET_IEP_GOALS] = [
  'goal_id', 'student_id', 'school_year', 'area', 'goal_text', 'baseline',
  'target_criterion', 'entered_date', 'status', 'completed_date',
  'outcome_note', 'linked_intervention_id', 'revised_from_goal_id',
  'created_by', 'created_at'
];
// Phase 40b: the actual ELC accommodations/modifications checklist (see
// AccommodationsChecklist.gs) -- one row per CHECKED item only, never a
// row per possible checklist item, so an unused checklist doesn't create
// ~70 blank rows per student. Unchecking an item deletes its row rather
// than flagging it false. (type, category, item) together are the natural
// key for one student -- there's no separate lookup id needed beyond
// entry_id, which exists only so updateRow_ has something stable to key
// a responsible_party edit off of.
SHEET_SCHEMAS[SHEET_ACCOMMODATIONS] = [
  'entry_id', 'student_id', 'type', 'category', 'item', 'responsible_party',
  'created_by', 'created_at'
];
// 504 Plan (2026-09-11) -- one row per student (upsert by student_id, same
// pattern as Staff_Access), not one row per field, since diagnosis/
// medications/service_areas/date_plan_implemented are always edited and
// read together as a single plan, never independently. Genuinely PHI, not
// just PII -- see Section504.gs for the access model (view: any staff who
// can already open this student, same as everything else on their
// profile; edit: Administrator/ELC Staff only) and PRIVACY.md.
SHEET_SCHEMAS[SHEET_504_PLANS] = [
  'student_id', 'diagnosis', 'medications', 'service_areas',
  'date_plan_implemented', 'last_updated_by', 'last_updated_at'
];
// Email Log (2026-09-14) -- every automated notification email this app
// ever attempts to send, logged from the one shared choke point every
// caller already goes through (sendNotificationEmail_, Notifications.gs)
// rather than each caller logging separately. Answers "did this actually
// go out, to whom, and when" without needing to trust a limited-retention
// Apps Script execution log or someone's personal Gmail Sent folder.
SHEET_SCHEMAS[SHEET_EMAIL_LOG] = [
  'timestamp', 'subject', 'audience', 'to', 'cc', 'sent', 'redirected_test_mode', 'real_to',
  // 2026-09-24, real find: `sent` used to be set from EMAIL_NOTIFICATIONS_ENABLED
  // alone, logged BEFORE MailApp.sendEmail even ran -- a real send failure
  // (quota, malformed address, transient API error) was invisible, logged
  // as a false "SENT". sendNotificationEmail_ (Notifications.gs) now
  // actually calls MailApp.sendEmail inside a try/catch and records the
  // real thrown message here when it fails, instead of nothing at all.
  'error'
];
// See SHEET_YEAR_END_ARCHIVE's own comment above for why this exists. One
// row per student per archived school year, written by
// buildYearEndArchiveRows_/bulkAdvanceGrades (Roster.gs). measures_json is a
// JSON blob of { measure_id: { tier, raw_score, max_score } } for that
// student's latest known result per measure as of archiving -- kept as a
// real snapshot, not a live join, so a later data correction can never
// silently rewrite what this record shows.
SHEET_SCHEMAS[SHEET_YEAR_END_ARCHIVE] = [
  'archive_id', 'student_id', 'first_name', 'last_initial', 'grade', 'school_year',
  'final_bucket', 'last_assessment_date', 'measures_json', 'archived_at', 'archived_by'
];
// Section 504 Plan history (2026-09-14, at the school's request -- same
// "never silently overwritten" treatment IEP Goals already get) -- one
// row per PAST version, written by archiveSection504Plan_ (Section504.gs)
// right before an edit or delete would otherwise lose it. Section_504_Plans
// itself stays the single current/live row per student; this is purely an
// append-only record of what it used to say.
SHEET_SCHEMAS[SHEET_504_HISTORY] = [
  'history_id', 'student_id', 'diagnosis', 'medications', 'service_areas',
  'date_plan_implemented', 'last_updated_by', 'last_updated_at',
  'archived_at', 'archived_by', 'archived_reason'
];

// Phase 24 (performance): every readAllRows_/appendRow_/updateRow_/deleteRows_
// call independently re-ran getOrCreateSpreadsheet_() (a SpreadsheetApp.openById
// round trip) AND getOrCreateSheet_() (a getSheetByName lookup plus a header-
// width migration check) -- and a single request routinely calls these
// several times over (getPrincipalDashboard alone reads Students, Sessions,
// Results, Requests, and Interventions). None of that can change mid-request
// (nothing else touches which spreadsheet backs this script, or a sheet's
// column structure, while one execution is running), so caching the resolved
// handles for the LIFETIME OF ONE EXECUTION is safe -- these Apps Script
// script-level vars reset on the next invocation regardless, exactly the
// scope this needs. This only memoizes the object HANDLES, never row data --
// every actual read still calls getRange()/getValues() fresh, so nothing
// about correctness changes, just how many times the handles themselves get
// re-resolved.
var _cachedSpreadsheet_ = null;
var _cachedSheets_ = {};

// Real find, 2026-09-26 (independent code review, "architecture", done at
// the administrator's explicit direction): a single request routinely reads
// the SAME sheet's full row data more than once (e.g. loading the Dashboard
// calls getPrincipalDashboard, getComplianceReport, and getCohortGrowthReport
// together, each independently re-reading Students/Sessions/Results from
// scratch). Like _cachedSpreadsheet_/_cachedSheets_ above, this is scoped to
// the LIFETIME OF ONE EXECUTION ONLY -- a script-level var that resets on
// every new request regardless, so it can never serve data across two
// different page loads or two different users; nothing about cross-request
// staleness is possible here. Unlike those two (which only cache object
// HANDLES), this caches actual ROW DATA, so it MUST be invalidated the
// moment anything writes to that sheet -- appendRow_/appendRows_/updateRow_/
// deleteRows_ below all clear their sheet's entry immediately after writing,
// so a read-after-write later in the SAME execution always sees the fresh
// data, never a stale pre-write snapshot.
var _rowsCache_ = {};

/**
 * Returns the backing spreadsheet, creating it (and all tabs) on first run.
 *
 * Guarded by a script lock: without it, two near-simultaneous first-ever
 * requests (two tabs, a quick refresh, etc.) can both see "not created yet"
 * and both call SpreadsheetApp.create(), leaving one orphaned duplicate.
 * The lock plus a re-check of the property after acquiring it (double-checked
 * locking) makes creation happen exactly once.
 */
function getOrCreateSpreadsheet_() {
  if (_cachedSpreadsheet_) return _cachedSpreadsheet_;

  var props = PropertiesService.getScriptProperties();
  var storedId = props.getProperty(SPREADSHEET_ID_PROP);

  if (storedId) {
    try {
      _cachedSpreadsheet_ = SpreadsheetApp.openById(storedId);
      return _cachedSpreadsheet_;
    } catch (e) {
      // Spreadsheet was deleted or inaccessible — fall through and recreate.
    }
  }

  var lock = LockService.getScriptLock();
  lock.waitLock(30000);
  try {
    // Re-check: another request may have created it while we waited for the lock.
    storedId = props.getProperty(SPREADSHEET_ID_PROP);
    if (storedId) {
      try {
        _cachedSpreadsheet_ = SpreadsheetApp.openById(storedId);
        return _cachedSpreadsheet_;
      } catch (e) {
        // Still gone — fall through and recreate.
      }
    }

    var ss = SpreadsheetApp.create(SPREADSHEET_NAME);
    props.setProperty(SPREADSHEET_ID_PROP, ss.getId());

    Object.keys(SHEET_SCHEMAS).forEach(function(name) {
      getOrCreateSheet_(ss, name);
    });

    // Seed the access allow-list with whoever is provisioning this spreadsheet,
    // so the deploying admin isn't locked out of their own tool. Everyone else
    // (including other ELC staff) must be added as a row on Staff_Access.
    var accessSheet = ss.getSheetByName(SHEET_ACCESS);
    accessSheet.appendRow([Session.getEffectiveUser().getEmail(), new Date(), 'Auto-added: provisioned this spreadsheet']);

    // Remove the default blank "Sheet1" left over from SpreadsheetApp.create,
    // now that our real tabs exist.
    var defaultSheet = ss.getSheetByName('Sheet1');
    if (defaultSheet && ss.getSheets().length > 1) {
      ss.deleteSheet(defaultSheet);
    }

    _cachedSpreadsheet_ = ss;
    return ss;
  } finally {
    lock.releaseLock();
  }
}

/**
 * Returns a tab by name, creating it with its header row if missing.
 */
function getOrCreateSheet_(ss, name) {
  if (_cachedSheets_[name]) return _cachedSheets_[name];

  var sheet = ss.getSheetByName(name);
  var headers = SHEET_SCHEMAS[name];
  if (!headers) throw new Error('Unknown sheet: ' + name);

  if (!sheet) {
    sheet = ss.insertSheet(name);
    sheet.appendRow(headers);
    var headerRange = sheet.getRange(1, 1, 1, headers.length);
    headerRange.setBackground('#1d4ed8');
    headerRange.setFontColor('#ffffff');
    headerRange.setFontWeight('bold');
    sheet.setFrozenRows(1);
  } else {
    // SHEET_SCHEMAS can grow over time (e.g. adding a new optional column to
    // an already-deployed, already-populated tab) -- appendRow_/readAllRows_
    // both operate on the schema's column COUNT/order regardless of what the
    // sheet's actual header row currently has, so an unmigrated sheet would
    // silently gain an unlabeled trailing data column. Extend the header row
    // (existing columns/data left untouched) whenever the schema has grown
    // past what's physically there yet.
    var existingWidth = sheet.getLastColumn();
    if (existingWidth < headers.length) {
      // This migration only ever APPENDS columns -- it assumes every column
      // already on the sheet still matches the schema at that same position.
      // That's held true so far because every past schema change only ever
      // appended too, but nothing enforced it. If a future change ever
      // inserted a column mid-array instead, this assertion fails loudly
      // (instead of silently writing new headers over what's really a
      // mismatched, misaligned sheet) so the mistake gets caught immediately.
      if (existingWidth > 0) {
        var existingHeaders = sheet.getRange(1, 1, 1, existingWidth).getValues()[0];
        var expectedPrefix = headers.slice(0, existingWidth);
        for (var h = 0; h < expectedPrefix.length; h++) {
          if (existingHeaders[h] !== expectedPrefix[h]) {
            throw new Error(
              'Header mismatch on "' + name + '": column ' + (h + 1) + ' is "' + existingHeaders[h] +
              '" on the sheet but SHEET_SCHEMAS expects "' + expectedPrefix[h] + '" at that position. ' +
              'Refusing to extend the header row until this is reconciled -- SHEET_SCHEMAS should only ever grow by appending.'
            );
          }
        }
      }
      var newHeaders = headers.slice(existingWidth);
      var addRange = sheet.getRange(1, existingWidth + 1, 1, newHeaders.length);
      addRange.setValues([newHeaders]);
      addRange.setBackground('#1d4ed8');
      addRange.setFontColor('#ffffff');
      addRange.setFontWeight('bold');
    }
  }
  _cachedSheets_[name] = sheet;
  return sheet;
}

/**
 * Structural fix (2026-08-04): Google Sheets can silently store a
 * digit-like cell (student_id, grade, grade_at_admin) as a JS Number
 * depending on how that cell happened to get formatted, but the client and
 * every other part of this app always treats those fields as an opaque
 * String. A bare `===`/`!==` comparison against a raw value read straight
 * off the sheet then silently fails across that type mismatch -- this bug
 * class was found and patched at 12+ individual comparison sites across
 * two separate incidents (see project_phase39_student_id_type_bug and
 * project_phase39_grade_type_bug) before this fix. Rather than relying on
 * every future comparison site to remember `String(...)` itself, this is
 * the ONE place a raw Sheets row becomes a header-mapped object --
 * coercing these fields here closes the bug class at its root. Existing
 * `String(a) === String(b)` call sites are unaffected (String(String(x))
 * === String(x)) and don't need to be un-done.
 *
 * Deliberately NOT a blanket "coerce everything to String" -- most fields
 * (notes, summary_json, dates) should keep whatever type they actually
 * are. Only the specific fields this bug class has actually hit.
 */
var STRING_COERCED_FIELDS_ = { student_id: true, grade: true, grade_at_admin: true };

/** Shared by readAllRows_/deleteRows_ -- the one place a raw Sheets row becomes a header-mapped object. */
function mapRowToObject_(headers, row) {
  var obj = {};
  headers.forEach(function(h, i) {
    var v = row[i];
    if (STRING_COERCED_FIELDS_[h] && v !== '' && v !== null && v !== undefined) {
      v = String(v);
    }
    obj[h] = v;
  });
  return obj;
}

/**
 * Reads every data row in `sheetName` as an array of header-mapped objects.
 *
 * Cached for the lifetime of this one execution (see _rowsCache_ above) --
 * returns a fresh shallow copy of the array AND of each row object every
 * call, never the exact same references twice, so a caller that mutates a
 * field on a returned row (rather than treating it as read-only) can never
 * corrupt what a later call in this same execution sees.
 */
function readAllRows_(sheetName) {
  if (_rowsCache_[sheetName]) {
    return _rowsCache_[sheetName].map(function(row) {
      var copy = {};
      for (var k in row) copy[k] = row[k];
      return copy;
    });
  }

  var ss = getOrCreateSpreadsheet_();
  var sheet = getOrCreateSheet_(ss, sheetName);
  var lastRow = sheet.getLastRow();
  if (lastRow < 2) {
    _rowsCache_[sheetName] = [];
    return [];
  }

  var headers = SHEET_SCHEMAS[sheetName];
  var values = sheet.getRange(2, 1, lastRow - 1, headers.length).getValues();
  var rows = values.map(function(row) { return mapRowToObject_(headers, row); });

  _rowsCache_[sheetName] = rows;
  return readAllRows_(sheetName); // return the freshly-cloned copy via the cache-hit path above
}

/** Appends one row built from `obj` (missing keys become blank cells). */
function appendRow_(sheetName, obj) {
  var ss = getOrCreateSpreadsheet_();
  var sheet = getOrCreateSheet_(ss, sheetName);
  var headers = SHEET_SCHEMAS[sheetName];

  var row = headers.map(function(h) {
    var v = obj[h];
    return (v === undefined || v === null) ? '' : v;
  });
  sheet.appendRow(row);
  delete _rowsCache_[sheetName]; // real find, 2026-09-26 -- a read-after-write later this same execution must see this row
}

/**
 * Phase 35 #5 (performance): batched version of appendRow_ -- writes every
 * object in `objs` in ONE multi-row getRange().setValues() call instead of
 * N separate appendRow_ calls (each of which is its own Sheets API round
 * trip). Same per-row shape/behavior as appendRow_ (missing keys become
 * blank cells); the only difference is one API call for the whole group
 * instead of one per row. Written for submitSession's per-measure
 * Assessment_Results rows -- a 5-measure CORE Phonics session went from 5
 * appendRow_ calls to 1. A no-op for an empty array (real Sheets API
 * getRange() requires numRows >= 1, so this guard also protects the caller
 * from ever needing to check for "any measures at all" itself).
 */
function appendRows_(sheetName, objs) {
  if (!objs || objs.length === 0) return;
  var ss = getOrCreateSpreadsheet_();
  var sheet = getOrCreateSheet_(ss, sheetName);
  var headers = SHEET_SCHEMAS[sheetName];

  var rows = objs.map(function(obj) {
    return headers.map(function(h) {
      var v = obj[h];
      return (v === undefined || v === null) ? '' : v;
    });
  });

  var startRow = sheet.getLastRow() + 1;
  sheet.getRange(startRow, 1, rows.length, headers.length).setValues(rows);
  delete _rowsCache_[sheetName]; // real find, 2026-09-26 -- see appendRow_'s own comment
}

/**
 * Updates the first row where `keyColumn` === `keyValue` by merging in
 * `patch`. Returns true if a row was found and updated.
 */
function updateRow_(sheetName, keyColumn, keyValue, patch) {
  // Real find, 2026-09-26: this used to read the whole sheet into memory,
  // find the match in that snapshot, then write back a full merged row --
  // with no locking. Two near-simultaneous writes to the same row (two staff
  // editing the same student, or the nightly FACTS sync overlapping a manual
  // edit) each worked from the same stale snapshot, so whichever write
  // landed second silently overwrote the first with stale data in every
  // column outside its own patch. A script-wide lock serializes the whole
  // read-modify-write so a second concurrent call always sees the first
  // call's result before reading its own snapshot -- same lock/timeout
  // pattern already used by getOrCreateSpreadsheet_ above.
  var lock = LockService.getScriptLock();
  lock.waitLock(30000);
  try {
    var ss = getOrCreateSpreadsheet_();
    var sheet = getOrCreateSheet_(ss, sheetName);
    var headers = SHEET_SCHEMAS[sheetName];
    var keyIdx = headers.indexOf(keyColumn);
    if (keyIdx === -1) throw new Error('Unknown column: ' + keyColumn);

    var lastRow = sheet.getLastRow();
    if (lastRow < 2) return false;

    var values = sheet.getRange(2, 1, lastRow - 1, headers.length).getValues();
    for (var i = 0; i < values.length; i++) {
      // String(...) on both sides -- found live while centralizing the
      // Number-vs-String coercion fix above: this bare === previously meant
      // updateStudent_/deactivateStudent (Roster.gs, keyColumn 'student_id')
      // would silently fail to find a student's row whenever Sheets stored
      // their student_id cell as a Number, same bug class as
      // mapRowToObject_ above, just on the WRITE-matching side instead of
      // the read side.
      if (String(values[i][keyIdx]) === String(keyValue)) {
        var rowNum = i + 2;
        // One batched write for the whole row instead of one setValue() call
        // per changed column -- matters once this runs in a per-student loop
        // (e.g. syncFactsRoster) rather than a single one-off edit.
        var existingRow = values[i];
        var newRow = headers.map(function(h, colIdx) {
          return Object.prototype.hasOwnProperty.call(patch, h) ? patch[h] : existingRow[colIdx];
        });
        sheet.getRange(rowNum, 1, 1, headers.length).setValues([newRow]);
        delete _rowsCache_[sheetName]; // real find, 2026-09-26 -- see appendRow_'s own comment (Data.gs)
        return true;
      }
    }
    return false;
  } finally {
    lock.releaseLock();
  }
}

/**
 * Deletes every row where predicate(rowObj) is true. Returns the count
 * removed. Genuinely removes the row (not a soft-delete) -- for correcting
 * a data-entry mistake (a mis-scored session, a revoked access grant), not
 * for anything meant to preserve history (students are soft-deleted via
 * deactivateStudent instead; see PRIVACY.md).
 *
 * Batched like updateRow_: one read of the whole sheet, one clear, one
 * write of whatever's kept -- not a per-row delete, which would also
 * corrupt row indices on every iteration.
 */
function deleteRows_(sheetName, predicate) {
  var ss = getOrCreateSpreadsheet_();
  var sheet = getOrCreateSheet_(ss, sheetName);
  var headers = SHEET_SCHEMAS[sheetName];

  var lastRow = sheet.getLastRow();
  if (lastRow < 2) return 0;

  var values = sheet.getRange(2, 1, lastRow - 1, headers.length).getValues();
  var kept = [];
  var deletedCount = 0;
  values.forEach(function(row) {
    // Same coercion as readAllRows_ (mapRowToObject_) -- a predicate here
    // comparing r.student_id/r.grade against a String should see the same
    // opaque String type readAllRows_ callers already do, not whatever
    // raw type Sheets happened to store.
    var obj = mapRowToObject_(headers, row);
    if (predicate(obj)) { deletedCount++; } else { kept.push(row); }
  });

  if (deletedCount === 0) return 0;

  // Real find, 2026-09-26: this used to clearContent() the WHOLE range first,
  // then write back only the surviving rows -- if that second call threw after
  // the clear already succeeded (a transient Sheets API error, a timeout),
  // every surviving row was gone too, not just the deleted ones. Now the kept
  // rows are written FIRST, into the top of the range -- if that throws, the
  // original untouched range (including the rows now duplicated at the top)
  // is still fully intact, just with a duplicate instead of a data loss. Only
  // after that write succeeds is the now-stale tail cleared.
  if (kept.length > 0) {
    sheet.getRange(2, 1, kept.length, headers.length).setValues(kept);
  }
  var tailStartRow = 2 + kept.length;
  var tailRowCount = values.length - kept.length;
  if (tailRowCount > 0) {
    sheet.getRange(tailStartRow, 1, tailRowCount, headers.length).clearContent();
  }
  delete _rowsCache_[sheetName]; // real find, 2026-09-26 -- see appendRow_'s own comment (above)
  return deletedCount;
}

/**
 * google.script.run can fail to properly deliver `Date` objects nested in a
 * returned value (a known Apps Script client-bridge quirk) -- forcing a
 * JSON round-trip here converts every Date to a plain ISO string first,
 * which serializes reliably. Every client-facing (google.script.run-called)
 * function should pass its return value through this before returning.
 */
function sanitizeForClient_(obj) {
  return JSON.parse(JSON.stringify(obj));
}

/**
 * Utility: URL/metadata of the backing spreadsheet, for admin/debug use only.
 * Deliberately logs no PII -- sheet names and a student COUNT, never any
 * student record.
 */
function getSpreadsheetUrl() {
  requireStaff_();
  var ss = getOrCreateSpreadsheet_();
  var info = {
    url: ss.getUrl(),
    id: ss.getId(),
    sheetNames: ss.getSheets().map(function(s) { return s.getName(); }),
    studentCount: readAllRows_(SHEET_STUDENTS).length,
    executingAs: Session.getEffectiveUser().getEmail()
  };
  console.log(JSON.stringify(info, null, 2));
  return info;
}

/* ===== Growth.gs ===== */
// ============================================================
//  Growth — cross-session trend + strengths/concerns synthesis.
//  Read-only analytics over Assessment_Sessions/Assessment_Results;
//  writing new sessions happens in Code.gs (submitSession).
// ============================================================

function parseJsonSafe_(str) {
  if (!str) return null;
  try { return JSON.parse(str); } catch (e) { return null; }
}

// Unified best-to-worst ordering across both tier vocabularies used in this
// app (DIBELS' 4-tier Blue/Green/Yellow/Red and the 3-tier Mastery/
// Strategic/Intensive used everywhere else). A given measure's points only
// ever use ONE of these vocabularies, so cross-vocabulary comparisons never
// actually happen -- this just needs a single consistent rank per string.
var TIER_RANK = { Red: 0, Intensive: 0, Yellow: 1, Strategic: 1, Green: 2, Blue: 3, Mastery: 3 };

// Measure_ids that represent the SAME underlying quantity scored against
// different benchmark charts, grouped so a student's trend isn't split
// into two disconnected lines just because one year's oral-reading-fluency
// check came from a DIBELS administration and another year's came from the
// Hasbrouck & Tindal WCPM check bundled into a Lexile/DRA session -- both
// are literally "words correct per minute."
var MEASURE_SERIES_GROUPS = {
  orf_words: 'oral_reading_fluency',
  orf_wcpm: 'oral_reading_fluency'
};

function seriesKeyFor_(measureId) {
  return MEASURE_SERIES_GROUPS[measureId] || measureId;
}

/**
 * Whether `measureId` (assessment_type `assessmentType`) is still given to
 * a student currently in grade `gradeKey` -- i.e. whether a strength/
 * concern built from an old result for this measure could ever be
 * re-tested and change. DIBELS/easyCBM/easyCBM Math each restrict several
 * measures to a grade band that stops well short of grade 8 (e.g. LNF/PSF
 * are DIBELS K-1 only, DIBELS_MEASURE_GRADES/Dibels.gs) -- once a student
 * ages out of that band, the measure is never administered to them again,
 * so a strength/concern still hanging on its last (possibly years-old)
 * tier is permanently unactionable, not just overdue. CORE Phonics parts
 * are intentionally excluded: CORE_PHONICS_AVAILABILITY's per-grade part
 * lists are strictly nested (K's parts subset 1's, 1's subset 2's, 2's
 * subset 3+'s "everything"), so a part once given is still given at every
 * higher grade -- nothing to age out of. Lexile/DRA's own scores
 * (lexile_score, dra_level) have no grade restriction at all. Returns true
 * (never hides data) whenever gradeKey or the measure itself is unknown --
 * only a real, on-file grade restriction can make this return false.
 */
function measureStillApplicableAtGrade_(assessmentType, measureId, gradeKey) {
  if (!gradeKey) return true;
  var table = assessmentType === 'dibels' ? DIBELS_MEASURE_GRADES
    : assessmentType === 'easycbm' ? EASYCBM_MEASURE_GRADES
    : assessmentType === 'easycbm_math' ? EASYCBM_MATH_MEASURE_GRADES
    : null;
  if (!table) return true;
  var grades = table[String(measureId || '').toUpperCase()];
  if (!grades) return true;
  return grades.indexOf(gradeKey) !== -1;
}

/**
 * Trend direction for one measure's time series. Primarily driven by tier
 * movement (comparing the earliest and latest points that actually carry a
 * tier), not raw score, because DIBELS/CORE Phonics cut scores rise as a
 * student advances grade/season -- a rising raw score can still mean the
 * student is falling further behind (e.g. "Red (improving)" when the tier
 * itself never left Red, or actually got worse). Falls back to comparing
 * raw scores only when fewer than two points have a tier at all (e.g. DRA,
 * Iowa, or a fully untiered/unpublished series).
 */
function computeTrend_(points) {
  if (points.length < 2) return 'insufficient data';

  var tiered = points.filter(function(p) { return p.benchmark_tier && TIER_RANK.hasOwnProperty(p.benchmark_tier); });
  if (tiered.length >= 2) {
    var firstRank = TIER_RANK[tiered[0].benchmark_tier];
    var lastRank = TIER_RANK[tiered[tiered.length - 1].benchmark_tier];
    if (lastRank > firstRank) return 'improving';
    if (lastRank < firstRank) return 'declining';
    // Tier held steady across the series -- report 'stable' even if the raw
    // score wobbled, rather than letting raw-score noise produce a claim
    // like "Red (improving)" that reads as contradicting the tier itself.
    return 'stable';
  }

  // No usable tier signal at all (e.g. DRA, Iowa, or an entirely untiered
  // series) -- raw score movement is the only signal available.
  var first = Number(points[0].raw_score);
  var last = Number(points[points.length - 1].raw_score);
  if (isNaN(first) || isNaN(last)) return 'insufficient data';
  return last > first ? 'improving' : (last < first ? 'declining' : 'stable');
}

/**
 * Full history for one student: every session, a per-measure time
 * series (for charting), and a synthesized strengths/concerns view
 * based on the MOST RECENT tier recorded for each measure.
 */
function getStudentHistory(studentId) {
  requireStaff_();
  if (!studentId) {
    console.error('getStudentHistory called with no studentId');
    throw new Error('getStudentHistory: studentId is required');
  }
  var student = getStudent(studentId);

  // Phase 39: a plain === here silently returned zero matches for any
  // student whose student_id Sheets stores as a numeric cell (every
  // FACTS-synced student) -- getValues() returns those as a JS Number,
  // while studentId always arrives as a String (client-side HTML
  // onclick="openStudent('...')" string-concatenates it). getStudent()
  // avoids this the same way -- String() on both sides -- everywhere
  // else that compares student_id should follow the same pattern.
  var sessions = readAllRows_(SHEET_SESSIONS)
    .filter(function(s) { return String(s.student_id) === String(studentId); })
    .map(function(s) {
      return {
        session_id: s.session_id,
        assessment_type: s.assessment_type,
        administration_date: s.administration_date,
        school_year: s.school_year,
        grade_at_admin: s.grade_at_admin,
        season: s.season,
        administered_by: s.administered_by,
        administrator_role: s.administrator_role || '',
        notes: s.notes || '',
        test_grade_level: s.test_grade_level || '',
        summary: parseJsonSafe_(s.summary_json)
      };
    })
    .sort(function(a, b) { return new Date(a.administration_date) - new Date(b.administration_date); });

  var sessionDateById = {};
  sessions.forEach(function(s) { sessionDateById[s.session_id] = s; });

  var results = readAllRows_(SHEET_RESULTS).filter(function(r) { return String(r.student_id) === String(studentId); });

  // Group results by series key (usually measure_id, but see
  // MEASURE_SERIES_GROUPS above), carrying the parent session's date/grade/
  // season and each point's own grade/season-appropriate benchmark reference.
  var byMeasure = {};
  results.forEach(function(r) {
    var session = sessionDateById[r.session_id];
    if (!session) return; // orphaned result row; skip
    var seriesKey = seriesKeyFor_(r.measure_id);
    if (!byMeasure[seriesKey]) byMeasure[seriesKey] = [];
    byMeasure[seriesKey].push({
      session_id: r.session_id,
      measure_id: r.measure_id,
      date: session.administration_date,
      assessment_type: r.assessment_type,
      raw_score: r.raw_score,
      max_score: r.max_score,
      benchmark_tier: r.benchmark_tier,
      benchmark_reference: getBenchmarkReference_(r.assessment_type, r.measure_id, session.grade_at_admin, session.season, r.max_score, r.raw_score),
      below_benchmark_floor: r.assessment_type === 'dibels' && isBelowLowestDibelsBand_(r.measure_id, session.grade_at_admin, session.season, r.raw_score),
      // 2026-09-26, at the school's request ("what letter was chosen...
      // isn't the letter supposed to correlate with a grade and time of
      // year? what does 2 mean"): dra_level's raw_score is always the
      // DERIVED DRA NUMBER (see Registry.gs's dra.score), not the Guided
      // Reading Level LETTER staff actually typed -- a bare number like "2"
      // means nothing to someone who thinks in GRL letters. The letter
      // itself is persisted separately as item_detail_json (only for
      // sessions saved after the 2026-09-18 fix that started keeping it --
      // see renderDraScoreEditFields_, Index.html, for the honest gap on
      // older sessions) -- surfaced here so the client can show "Guided
      // Reading Level B (DRA 2, Kindergarten)" instead of just "2".
      item_detail: r.item_detail_json ? parseJsonSafe_(r.item_detail_json) : null
    });
  });

  var measureSeries = {};
  var strengths = [];
  var concerns = [];
  var currentGradeKey = normalizeGradeKey_(student.grade);

  Object.keys(byMeasure).forEach(function(seriesKey) {
    var points = byMeasure[seriesKey].sort(function(a, b) { return new Date(a.date) - new Date(b.date); });
    var trend = computeTrend_(points);

    measureSeries[seriesKey] = { points: points, trend: trend };

    // Use the most recent NON-null tier, not strictly the literal last point --
    // a null tier can legitimately occur on a real data point (e.g. a CORE
    // Phonics session where only a partial letter/sound battery was given for
    // that grade/season) without meaning "no tier has ever been recorded."
    // Falling back to the last real tier avoids a student silently vanishing
    // from both Strengths and Concerns just because their most recent session
    // happened to be a partial one.
    var latestTier = null;
    var latestTierDate = null;
    var latestTierPoint = null;
    for (var i = points.length - 1; i >= 0; i--) {
      if (points[i].benchmark_tier) { latestTier = points[i].benchmark_tier; latestTierDate = points[i].date; latestTierPoint = points[i]; break; }
    }

    // Real find (2026-09-22, Jonah D. case): LNF/PSF are only ever
    // administered K-1 (DIBELS_MEASURE_GRADES, Dibels.gs) -- a strong (or
    // Red/Intensive) score from back then used to keep showing up as a
    // permanent Strength/Concern forever, with nothing to say the measure
    // isn't even given anymore at the student's CURRENT grade -- and, for a
    // concern, no way it could ever resolve, since it's never retested. At
    // the school's explicit request, such a point is dropped from both
    // lists entirely (not just marked stale) the moment it's no longer
    // applicable at the student's current grade -- see
    // measureStillApplicableAtGrade_'s own comment for exactly which
    // measures this can affect and why CORE Phonics/Lexile/DRA are exempt.
    if (latestTierPoint && !measureStillApplicableAtGrade_(latestTierPoint.assessment_type, latestTierPoint.measure_id, currentGradeKey)) {
      return;
    }

    if (STRENGTH_TIERS.indexOf(latestTier) !== -1) {
      // Concerns already solved the "still applicable but overdue" case
      // (see the stale/last_assessed_school_year fields just below) --
      // widened to strengths too, at the school's request, instead of
      // leaving them a plain string array with no staleness signal.
      var strengthSchoolYear = schoolYearForDate_(new Date(latestTierDate));
      strengths.push({
        measure: seriesKey,
        tier: latestTier,
        trend: trend,
        last_assessed_school_year: strengthSchoolYear,
        stale: strengthSchoolYear !== currentSchoolYear_()
      });
    } else if (CONCERN_TIERS.indexOf(latestTier) !== -1) {
      // Phase 37 (finding #17): unlike Dashboard.gs's schoolwide rollup
      // (where a stale tier now gets re-routed to "not yet assessed" for
      // COUNTING purposes), a single student's profile should keep showing
      // a real concern even if it's old -- silently dropping it would look
      // like the concern resolved itself. Instead it's explicitly labeled
      // stale so it can't be mistaken for a current result. (This is the
      // "still applicable, just overdue" case -- a genuinely no-longer-
      // applicable measure was already filtered out above instead.)
      var concernSchoolYear = schoolYearForDate_(new Date(latestTierDate));
      concerns.push({
        measure: seriesKey,
        tier: latestTier,
        trend: trend,
        last_assessed_school_year: concernSchoolYear,
        stale: concernSchoolYear !== currentSchoolYear_()
      });
    }
  });

  return sanitizeForClient_({
    student: student,
    sessions: sessions,
    measureSeries: measureSeries,
    strengths: strengths,
    concerns: concerns,
    riskTrajectory: computeStudentRiskTrajectory_(sessions, results, sessionDateById)
  });
}

/**
 * 2026-09-26, at the administrator's explicit request ("no real way of
 * looking at a student over time and are they trending up or worse"):
 * measureSeries above is one chart PER MEASURE, and nothing bridges a
 * measure that ages out (LNF/PSF stopping after Grade 1) or changes
 * assessment type entirely (DIBELS -> easyCBM at Grade 4) -- seeing this
 * ONE student's overall trajectory today means eyeballing several
 * unrelated small charts and mentally stitching them together. Reuses the
 * exact same "one combined risk bucket as of a cutoff" machinery
 * (bucketAsOf_/overallRiskBucket_) already built for the schoolwide
 * Dashboard's movement_summary, Trend #2's getCohortGrowthReport, and
 * Trend #5's computeDecliningStudents_ (Dashboard.gs) -- scoped here to
 * ONE student's own periods instead of a cohort/roster, so it reads
 * straight across whatever assessment types or measures actually produced
 * each period's data, exactly the kind of continuity a single per-measure
 * chart can't give.
 *
 * One point per distinct (school_year, season) period THIS student
 * actually has a session in, chronological, each carrying the grade they
 * were in at that time and their one combined bucket as of that period's
 * cutoff (same same-school-year-only tier eligibility rule bucketAsOf_
 * uses elsewhere, so a Fall snapshot never silently inherits a stale
 * prior-year tier).
 */
function computeStudentRiskTrajectory_(sessions, results, sessionDateById) {
  var points = [];
  results.forEach(function(r) {
    if (!r.benchmark_tier) return;
    var session = sessionDateById[r.session_id];
    if (!session) return;
    points.push({ measure_id: seriesKeyFor_(r.measure_id), tier: r.benchmark_tier, time: new Date(session.administration_date).getTime() });
  });

  /** See riskBucketAsOf_'s own comment (Dashboard.gs, above overallRiskBucket_) for what this computes and why. */
  function bucketAsOf_(cutoffTime) {
    return riskBucketAsOf_(points, cutoffTime);
  }

  var periodCutoffs = {};
  var periodGrade = {};
  sessions.forEach(function(s) {
    var key = (s.school_year || '(no school year)') + '|' + (s.season || '(no season)');
    var t = new Date(s.administration_date).getTime();
    if (!periodCutoffs[key] || t > periodCutoffs[key]) { periodCutoffs[key] = t; periodGrade[key] = s.grade_at_admin; }
  });

  return Object.keys(periodCutoffs).sort(function(a, b) { return periodCutoffs[a] - periodCutoffs[b]; }).map(function(key) {
    return { period: key, grade: String(periodGrade[key] || ''), bucket: bucketAsOf_(periodCutoffs[key]) };
  });
}

/**
 * Run-from-editor diagnostic (2026-09-17): pinpoints a report showing
 * conflicting DIBELS Composite statuses for the same student -- e.g. "Red"
 * in Areas of Concern but "Meeting expectations" in Latest Scores, on the
 * same printed Student Assessment Report. Two independent, real causes can
 * each produce this on their own:
 *
 * (1) buildStudentReportHtml_'s "Latest Scores" table (Index.html) uses the
 *     LITERAL last chronological point (series.points[points.length-1]),
 *     while the "Areas of Concern" list (h.concerns, computed above in
 *     getStudentHistory) deliberately walks BACKWARD past any null-tier
 *     point to the most recent point that actually HAS a tier. If the
 *     truly latest point has a null tier for any reason, the two sections
 *     of the same report can describe two different dated points without
 *     any label saying so.
 *
 * (2) measureStatusBadge_/pointStatusText_ (Index.html) treat "no tier
 *     recorded" as "Meeting expectations" whenever a benchmark_reference
 *     number also exists -- correct for Lexile/DRA/ORF/easyCBM (which
 *     really do have no tier when the score is good), but WRONG for
 *     DIBELS: getBenchmarkReference_'s DIBELS branch (Registry.gs) always
 *     returns bands[0].min (the Blue tier's threshold) as long as ANY
 *     bands exist for that grade/season -- even when the actual score fell
 *     BELOW every published band (e.g. below the Composite's Red floor,
 *     min 200 for every grade -- mathematically possible from the z-score
 *     formula for a very low performer). scoreDibels then correctly
 *     returns tier=null for "below every band," but the report display
 *     can't tell that apart from "no tier because it's fine" -- and shows
 *     the single worst possible score as "Meeting expectations."
 *
 * This prints every recorded DIBELS Composite result for the named
 * student, in date order, with enough detail to tell which of the two
 * causes (or both) is actually in play. Prints first name + last INITIAL
 * only, per this app's usual PII-in-logs minimization.
 */
function diagnoseStudentDibelsComposite_(nameQuery) {
  requireAdministrator_(); // real find, 2026-09-26
  var q = String(nameQuery || '').trim().toLowerCase();
  if (!q) throw new Error('Pass part of the student\'s name, e.g. diagnoseStudentDibelsComposite_("Calloway").');

  var students = readAllRows_(SHEET_STUDENTS).filter(function(s) {
    return (String(s.first_name || '') + ' ' + String(s.last_name || '')).toLowerCase().indexOf(q) !== -1;
  });
  if (students.length === 0) { console.log('No student matched "' + nameQuery + '".'); return; }

  var sessionsById = {};
  readAllRows_(SHEET_SESSIONS).forEach(function(s) { sessionsById[s.session_id] = s; });
  var allResults = readAllRows_(SHEET_RESULTS);

  students.forEach(function(student) {
    var label = student.first_name + ' ' + (student.last_name || '').charAt(0) + '. (student_id ' + student.student_id + ', grade ' + student.grade + ')';
    console.log('=== ' + label + ' ===');

    var composites = allResults
      .filter(function(r) { return String(r.student_id) === String(student.student_id) && r.assessment_type === 'dibels' && r.measure_id === 'composite'; })
      .map(function(r) {
        var session = sessionsById[r.session_id];
        return {
          date: session ? session.administration_date : null,
          grade_at_admin: session ? session.grade_at_admin : null,
          season: session ? session.season : null,
          raw_score: r.raw_score,
          stored_tier: r.benchmark_tier
        };
      })
      .filter(function(r) { return r.date; })
      .sort(function(a, b) { return new Date(a.date) - new Date(b.date); });

    if (composites.length === 0) { console.log('  No DIBELS Composite results on file.'); return; }

    composites.forEach(function(c, i) {
      var fresh = scoreDibels('COMPOSITE', c.grade_at_admin, c.season, Number(c.raw_score));
      var reference = getBenchmarkReference_('dibels', 'composite', c.grade_at_admin, c.season, null, c.raw_score);
      var bands = DIBELS_BENCHMARKS.COMPOSITE[normalizeGradeKey_(c.grade_at_admin)] && DIBELS_BENCHMARKS.COMPOSITE[normalizeGradeKey_(c.grade_at_admin)][DIBELS_SEASON_TO_PERIOD[c.season]];
      var lowestBandMin = bands ? bands[bands.length - 1].min : null; // bands are ordered best-to-worst; last = Red's floor
      var isLatest = i === composites.length - 1;
      console.log('  ' + (isLatest ? '[LATEST] ' : '') + c.date + ' (grade ' + c.grade_at_admin + ', ' + c.season + '): raw_score=' + c.raw_score
        + ', stored_tier="' + (c.stored_tier || '(none)') + '", freshly-recomputed_tier="' + (fresh.tier || '(none)') + '"'
        + ', benchmark_reference=' + reference + ', lowest_published_band_min=' + lowestBandMin
        + (fresh.tier === null && lowestBandMin !== null && Number(c.raw_score) < lowestBandMin
            ? ' <-- BELOW every published band (worse than Red) -- this is cause (2): a null tier here does NOT mean "meeting expectations," it means "worse than the worst published tier."'
            : ''));
    });

    console.log('  getStudentHistory\'s own "Areas of Concern" walks backward from the bottom of this list to the most recent row with a non-empty stored_tier -- if that is NOT the [LATEST] row above, that\'s cause (1): Latest Scores and Areas of Concern are describing two different dates.');
  });
}


/**
 * For the named student's MOST RECENT DIBELS session, compares what was
 * actually recorded against DIBELS_COMPOSITE_PARAMS' required measure list
 * for that session's grade -- i.e. exactly what ELC needs to go back and
 * enter for the Composite to calculate. Written after the fact (the
 * phantom composite placeholder row that would have carried this same
 * "missing" list is deleted by deleteOrphanedNullScoreResults, so this
 * re-derives it straight from the real per-measure results instead).
 * Prints first name + last INITIAL only, per this app's usual
 * PII-in-logs minimization.
 */
function diagnoseStudentMissingDibelsMeasures_(nameQuery) {
  requireAdministrator_(); // real find, 2026-09-26
  var q = String(nameQuery || '').trim().toLowerCase();
  if (!q) throw new Error('Pass part of the student\'s name, e.g. diagnoseStudentMissingDibelsMeasures_("Calloway").');

  var student = readAllRows_(SHEET_STUDENTS).filter(function(s) {
    return (String(s.first_name || '') + ' ' + String(s.last_name || '')).toLowerCase().indexOf(q) !== -1;
  })[0];
  if (!student) { console.log('No student matched "' + nameQuery + '".'); return; }
  var label = student.first_name + ' ' + (student.last_name || '').charAt(0) + '.';

  var dibelsSessions = readAllRows_(SHEET_SESSIONS)
    .filter(function(s) { return String(s.student_id) === String(student.student_id) && s.assessment_type === 'dibels'; })
    .sort(function(a, b) { return new Date(b.administration_date) - new Date(a.administration_date); });
  if (dibelsSessions.length === 0) { console.log(label + ': no DIBELS sessions on file.'); return; }

  var latest = dibelsSessions[0];
  var gradeKey = normalizeGradeKey_(latest.grade_at_admin);
  var params = DIBELS_COMPOSITE_PARAMS[gradeKey];
  console.log(label + '\'s most recent DIBELS session: ' + latest.administration_date + ' (grade ' + gradeKey + ', ' + latest.season + ').');
  if (!params) { console.log('No Composite formula is published for grade ' + gradeKey + ' -- nothing to enter, this grade just isn\'t supported for an auto-calculated Composite.'); return; }

  var required = Object.keys(params.weights);
  var recordedMeasureIds = {};
  readAllRows_(SHEET_RESULTS)
    .filter(function(r) { return r.session_id === latest.session_id; })
    .forEach(function(r) { recordedMeasureIds[String(r.measure_id).toUpperCase()] = r.raw_score; });

  console.log('Required for the grade ' + gradeKey + ' Composite: ' + required.join(', '));
  required.forEach(function(m) {
    var has = Object.prototype.hasOwnProperty.call(recordedMeasureIds, m);
    console.log('  ' + m + ' (' + ((DIBELS_MEASURES[m] || {}).label || m) + '): ' + (has ? 'recorded (' + recordedMeasureIds[m] + ')' : 'MISSING -- needs to be entered'));
  });
}


/**
 * Every Assessment_Results row with a blank/null raw_score -- these are all
 * phantom placeholder rows from the bug fixed 2026-09-17 in Code.gs's
 * submitSession (a measure that couldn't actually be scored, most commonly
 * a DIBELS Composite missing required sub-measures, used to get written to
 * Assessment_Results as a real permanent row anyway). A genuinely real
 * result NEVER has a blank raw_score -- every scoring path in Registry.gs
 * either has a real entered/calculated number or omits the measure key
 * entirely -- so this predicate can't accidentally catch a legitimate
 * result. Going forward submitSession no longer creates these; this is
 * only for cleaning up ones that already exist from before that fix.
 */
function findOrphanedNullScoreResults_() {
  requireAdministrator_(); // real find, 2026-09-26
  var sessionsById = {};
  readAllRows_(SHEET_SESSIONS).forEach(function(s) { sessionsById[s.session_id] = s; });
  var studentsById = {};
  readAllRows_(SHEET_STUDENTS).forEach(function(s) { studentsById[String(s.student_id)] = s; });

  return readAllRows_(SHEET_RESULTS)
    .filter(function(r) { return r.raw_score === '' || r.raw_score === null || r.raw_score === undefined; })
    .map(function(r) {
      var session = sessionsById[r.session_id] || {};
      var student = studentsById[String(r.student_id)] || {};
      return {
        result_id: r.result_id,
        session_id: r.session_id,
        student_label: (student.first_name || '?') + ' ' + (student.last_name || '').charAt(0) + '.',
        date: session.administration_date || '(unknown)',
        assessment_type: r.assessment_type,
        measure_id: r.measure_id
      };
    });
}

